(window.GIM_TS=window.GIM_TS||{})["Zevachim.4"]={"from":96,"a":[["ודבר זה נלמד \u0003מ\u0004דברי ה\u0003תנא דבי\u0004 \u0005[של בית\u0006 מדרשו של\u0005]\u0006 \u0003ר' ישמעאל\u0004 לעיל (זבחים מא,א).","ושואלים: \u0003דבר הלמד בהיקש מהו שילמד בבנין אב\u0004 בקדשים? \u0003אמר ר' ירמיה:\u0004 אם היה כן, ש\u0003לא לכתוב\u0004 \u0005[יכתוב]\u0006 \u0003צפונה\u0004 שחיטת צפון \u0003באשם,\u0004 כפי שהקישו הכתוב במפורש לחטאת ועולה (ראה לעיל זבחים מט,א—ב), \u0003ותיתי\u0004 \u0005[ותבוא,\u0006 תילמד\u0005]\u0006 הלכה זו \u0003מבנין אב מחטאת,\u0004 ששניהם קדשי קדשים הם, ובחטאת הרי נלמד דין שחיטת צפון מן ההיקש לעולה. \u0003למאי הלכתא כתביה\u0004 \u0005[\u0006ל\u0005מה,\u0006 לאיזו \u0005הלכה כתב אותו]?\u0006 \u0003לאו למימרא\u0004 \u0005[האם לא כדי לומר]\u0006 שבקדשים, \u0003דבר הלמד בהיקש אין חוזר ומלמד בבנין אב?\u0004","ושואלים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה מוכיח בדרך זו, יכול אתה לומר: מדוע הוקש במפורש אשם לעולה לענין זה? \u0003תיתי\u0004 \u0005[שתבוא,\u0006 תילמד\u0005]\u0006 הלכה זו \u0003מבנין אב מעולה\u0004 שבה נאמר דין צפון בפירוש! אלא, \u0003מאי טעמא לא אתי\u0004 \u0005[מה טעם אינה באה,\u0006 נלמדת משם] בבנין אב? \u0003משום דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך]\u0006 את הלימוד בבנין אב, ולומר: \u0003מה לעולה שכן\u0004 מחמיר הכתוב בה יותר מבאשם, שהיא עולה \u0003כליל.\u0004 אם כן \u0003חטאת נמי איכא למיפרך\u0004 \u0005[גם כן יש\u0006 מקום \u0005לפרוך]\u0006 ולומר: \u0003מה לחטאת\u0004 שהיא חמורה מאשם, \u0003שכן מכפרת על חייבי כריתות!\u0004 ואם כן, אין מכאן ראיה.","אגב כך שואלים: שלושה קרבנות אלו, עולה חטאת ואשם, \u0003חדא מחדא לא אתיא\u0004 \u0005[אחת מאחת אינה באה]\u0006 בבנין אב מכתוב אחד, \u0003תיתי חדא מתרתי\u0004 \u0005[תבוא\u0006 ותילמד \u0005אחת משתים]\u0006 בבנין אב משני כתובים.","ומשיבים: \u0003מהי תיתי\u0004 \u0005[מאלו תבוא]?\u0006 \u0003לא נכתוב\u0004 \u0003רחמנא\u0004 \u0005[תכתוב התורה]\u0006 צפון ב\u0003עולה ותיתי\u0004 \u0005[ותבוא,\u0006 תילמד\u0005]\u0006 הלכה זו \u0003מחטאת ואשם\u0004 — יש לפרוך: \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן מכפרין,\u0004 מה שאין כן העולה שאינה לכפרה אלא למתנה!","ואם תאמר ש\u0003לא נכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 \u0003בחטאת ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד \u0005מאלה]\u0006, אשם ועולה — יש לפרוך: \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן\u0004 באים רק מבהמות \u0003זכרים,\u0004 וחטאת יחיד באה נקיבה!","ואם תאמר ש\u0003לא נכתוב\u0004 \u0005[תכתוב\u0006 התורה\u0003]\u0004 \u0003באשם ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד \u0005מאלה]\u0006 מעולה וחטאת — יש לדחות: \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן ישנן בציבור\u0004 \u0003כביחיד,\u0004 ואילו אשם לעולם אינו בא כקרבן ציבור.","עד כאן דנו בדבר הלמד מהיקש, ומעתה דנים בדברים הנלמדים במידות אחרות. ושואלים: \u0003דבר הלמד בגזירה שוה מהו שילמד\u0004 אחר כך \u0003בהיקש? אמר רב פפא: \"וזאת תורת זבח השלמים... אם על תודה\u0004 יביאנו\" (ויקרא ז, יא— יב) — מהיקש זה של תודה לשלמים \u0003למדנו לתודה שבא מן המעשר\u0004 שיכול להביא קרבן תודה מכספי פדיון מעשר שני, \u0003מדאשכחן\u0004 \u0005[מ\u0006מה \u0005שמצאנו]\u0006 \u0003שלמים דאתו\u0004 \u0005[שבאים]\u0006 \u0003ממעשר.\u0004","והרי \u0003שלמים גופייהו מנא לן\u0004 \u0005[עצמם מנין לנו]\u0006 שבאים ממעות מעשר? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 בשלמים \u0003\"שם\"\u0004 (\"וזבחת שלמים ואכלת שם\", דברים כז, ז), ונאמר במעשר \u0003\"שם\"\u0004 (\"ואכלת... במקום אשר יבחר לשכן שמו שם מעשר דגנך\" וכו', דברים יד, כג) וגזירה שווה היא. הרי שדבר שנלמד בגזירה שווה חוזר ומלמד בהיקש (שמקישים את התודה לשלמים).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי לרבינא:\u0004 מכאן אין הוכחה, שהרי \u0003מעשר דגן\u0004 (ובכללו מעשר שני) \u0003חולין בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא,\u0004 ואין בלימוד ממנו אותה הגבלה שיש בקדשים, שאין למדים למד מלמד!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 וכי מי ש\u0003אמר\u0004 שאין דנים בקדשים למד מלמד \u0003אמרה\u0004 רק במקרה שגם ה\u0003למד\u0004 הוא \u0003קדש ו\u0004גם \u0003מלמד קדש?\u0004 אלא גם אם רק הלמד קודש, שוב אינו יכול ללמוד ממנו לדבר אחר בקדשים.","ועוד שואלים: \u0003דבר הלמד בגזירה שוה מהו\u0004 \u0003שילמד בגזירה שוה? אמר רמי בר חמא, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 בענין לחמי התודה, שיש בהם שלושה מינים, רבוכה (מבושלת תחילה במים), חלות ורקיקים: \u0003\"סלת מרבכת\"\u0004 (ויקרא ז, יב) — \u0003למדנו ל\u0004מנחה \u0003רבוכה שבאה סולת,\u0004 ואולם שצריך סולת גם עבור","\u0003חלות\u0004 של תודה \u0003מניין? תלמוד לומר \"חלות\" \"חלות\"\u0004 בגזירה שווה, שנאמר \"סולת מורבכת חלות\" (ויקרא ז, יב) ונאמר \"חלות\" בחלות (ויקרא ז, יב). שצריך סולת במנחה של \u0003רקיקין\u0004 של תודה \u0003מניין? תלמוד לומר \"מצות\" \"מצות\",\u0004 שנאמר בחלות \"חלות מצות\", ונאמר ברקיקים \"רקיקי מצות\". הרי שלמדים גזירה שווה מגזירה שווה, חלות ממורבכת, ורקיקים מחלות.","\u0003אמר\u0004 \u0003ליה\u0004 \u0005[לו]\u0006 \u0003רבינא: ממאי\u0004 \u0005[ממה]\u0006 אתה מסיק שלגבי רקיקים \u0003\"מצות\" \"מצות\"\u0004 בגזירה שווה \u0003מחלות\u0004 של תודה \u0003גמר\u0004 \u0005[למד]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ממאפה תנור גמר\u0004 \u0005[למד],\u0006 שנאמר בו \"מצות\", ונאמר בו במפורש שהוא בא מן הסולת (ויקרא ב, ד)!","\u0003אלא אמר רבא,\u0004 מכאן יש להביא ראיה שדבר הלמד בגזירה שווה חוזר ומלמד בגזירה שווה, שכך \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 נאמר בפר כהן משיח, שהוא מן הפרים הנשרפים: \"ואת עור הפר ואת כל בשרו... \u0003וקרבו ופרשו, והוציא\u0004 את כל הפר אל מחוץ למחנה... ושרף אותו\" (ויקרא ד, יא— יב) — \u0003מלמד שמוציאו שלם,\u0004 ואינו מנתחו תחילה לנתחיו.","ויש לשאול: \u0003יכול ישרפנו שלם? נאמר כאן: \"ראשו וכרעיו\" ונאמר להלן\u0004 בקרבן עולה: \u0003\"ראשו וכרעיו\"\u0004 (ראה ויקרא א, יב— יג) \u0003מה להלן\u0004 בעולה \u0003על\u0004 \u0003ידי ניתוח, אף כאן על ידי ניתוח.\u0004","ומקשים: \u0003אי\u0004 \u0005[אם\u0006 כן\u0005]\u0006 תאמר \u0003גם:\u0004 \u0003מה להלן,\u0004 בעולה, הרי הוא \u0003בהפשט\u0004 שמפשיט את עורו קודם ששורפו על המזבח, \u0003אף כאן\u0004 בפר כהן משיח \u0003נמי\u0004 \u0005[גם כן]\u0006 יהא \u0003בהפשט\u0004 קודם שישרפנו! \u0003תלמוד לומר\u0004 בפר כהן משיח: \u0003\"וקרבו ופרשו\"\u0004 (ויקרא ד, יא). ועל ההוכחה האחרונה שואלים: \u0003מאי תלמודא\u0004 \u0005[מהו הלימוד]?\u0006 כלומר, כיצד נובעים דברים אלה מכתוב זה, שלכאורה אינו עוסק בהם? \u0003אמר רב פפא:\u0004 כך הלימוד, \u0003כשם שפרשו\u0004 נשאר \u0003בקרבו\u0004 כשמוציאים אותו מחוץ למחנה ושורפים אותו, ואין מוציאים את הפרש מן הקרביים, \u0003כך בשרו\u0004 נשאר \u0003בעורו\u0004 כשמנתחים אותו לנתחיו. הרי שלמדנו דין זה לפר כהן משיח בגזירה שווה.","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 לגבי פר ושעיר של יום הכיפורים, \u0003רבי אומר: נאמר כאן\u0004 \u0003עור ובשר ופרש\u0004 (ויקרא טז, כז),"],["\u0003ונאמר להלן\u0004 בפר כהן משיח \u0003עור ובשר ופרש\u0004 (ויקרא ד, יא), ויש ללמוד מגזירה שווה זו: \u0003מה להלן\u0004 בפר כהן משיח מדובר \u0003על ידי ניתוח שלא בהפשט\u0004 (כפי שלמדנו בגזירה שווה מעולה), \u0003אף כאן\u0004 בפר ושעיר של יום הכיפורים — \u0003על ידי ניתוח שלא בהפשט.\u0004 ואם כן למדים גזירה שווה מגזירה שווה אחרת.","ועוד שואלים: \u0003דבר הלמד בגזירה שוה מהו שילמד בקל וחומר?\u0004 ומשיבים: \u0003קל וחומר\u0004 הוא: \u0003ומה היקש שאינו מלמד בהיקש,\u0004 ולמדנו דבר זה \u0003אי\u0004 \u0005[או]\u0006 \u0003מ\u0004דברי \u0003רבא אי\u0004 \u0005[או]\u0006 \u0003מ\u0004דברי \u0003רבינא\u0004 (לעיל זבחים מט,ב), בכל זאת הוא \u0003מלמד בקל וחומר מ\u0004תוך הדרשה של ה\u0003תנא דבי\u0004 \u0005[של בית]\u0006 מדרשו של \u0003ר' ישמעאל\u0004 (לעיל זבחים מא,א), \u0003גזירה שוה המלמדת בהיקש מ\u0004מה שהוכיח \u0003רב פפא\u0004 בעמוד הקודם (נ,א), \u0003אינו דין שתלמד בקל וחומר?\u0004","ואומרים: \u0003הניחא למאן דאית ליה\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שיש לו,\u0006 שמקבל\u0005]\u0006 את דברי \u0003רב פפא, אלא למאן דלית ליה\u0004 \u0005[ל\u0006דעת \u0005מי שאין\u0006 לו, שאינו מקבל\u0005]\u0006 את דברי \u0003רב פפא, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אלא\u0004 ה\u0003קל וחומר\u0004 הוא באופן אחר: \u0003ומה היקש שאין\u0004 חוזר ו\u0003מלמד בהיקש\u0004 אחר, \u0003אי\u0004 \u0005[או]\u0006 \u0003מ\u0004דברי \u0003רבא אי\u0004 \u0005[או]\u0006 \u0003מ\u0004דברי \u0003רבינא\u0004 — \u0003מלמד בקל וחומר מ\u0004דברי ה\u0003תנא דבי\u0004 \u0005[של בית]\u0006 \u0003ר' ישמעאל, גזירה שוה המלמדת בגזירה שוה חבירתה\u0004 כמו שהוכיח \u0003רמי בר חמא\u0004 בעמוד הקודם, \u0003אינו דין שתלמד בקל וחומר?\u0004 ומעתה דנים בדבר הלמד בקל וחומר.","ושואלים: \u0003דבר הלמד בגזירה שוה מהו שילמד בבנין אב?\u0004 שאלה זו לא נפתרה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003דבר הלמד בקל וחומר מהו שילמד בהיקש?\u0004 ואומרים: \u0003קל וחומר\u0004 הוא: \u0003ומה גזירה שוה שאינה למדה\u0004 מדבר הנלמד \u0003בהיקשא\u0004 \u0005[בהיקש],\u0006 \u0003מ\u0004דברי \u0003ר' יוחנן\u0004 (לעיל זבחים מט,ב), בכל זאת דבר הנלמד בגזירה שווה \u0003מלמד בהיקש מ\u0004מה שהוכיח \u0003רב פפא\u0004 בעמוד הקודם, \u0003קל וחומר הלמד מהיקש מ\u0004דברי ה\u0003תנא דבי\u0004 \u0005[של בית]\u0006 \u0003ר' ישמעאל\u0004 (לעיל זבחים מא,א), \u0003אינו דין שילמד בהיקש?\u0004","ואומרים: \u0003הניחא למאן דאית ליה\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שיש לו,\u0006 שמקבל\u0005]\u0006 את \u0003דברי\u0004 \u0003רב פפא, אלא למאן דלית ליה\u0004 \u0005[ל\u0006דעת \u0005מי שאין לו,\u0006 שאינו מקבל\u0005]\u0006 את \u0003דברי\u0004 \u0003רב פפא, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ואומרים: במקרה זה \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה.","ושואלים: \u0003דבר הלמד בקל וחומר מהו שילמד בגזירה שוה?\u0004 ומשיבים, \u0003קל וחומר\u0004 הוא: \u0003ומה גזירה שוה שאינה למידה\u0004 מדבר הנלמד \u0003בהיקשא\u0004 \u0005[בהיקש],\u0006 \u0003מ\u0004דברי \u0003ר' יוחנן\u0004 (לעיל זבחים מט,ב), בכל זאת \u0003מלמד בגזירה שוה מ\u0004דברי \u0003רמי בר חמא\u0004 בעמוד הקודם, \u0003קל וחומר הלמד\u0004 מדבר הנלמד \u0003בהיקש מ\u0004דברי ה\u0003תנא דבי\u0004 \u0005[של בית]\u0006 \u0003ר' ישמעאל\u0004 (לעיל זבחים מא,א) \u0003אינו דין שתלמד בגזירה שוה?\u0004","ושואלים עוד: \u0003דבר הלמד בקל וחומר, מהו ש\u0004יחזור ו\u0003ילמד בקל וחומר?\u0004 ומשיבים, \u0003קל וחומר\u0004 הוא: \u0003ומה גזירה שוה שאינה למידה\u0004 מדבר הנלמד \u0003בהיקש מ\u0004דברי \u0003ר' יוחנן\u0004 (לעיל זבחים מט,ב), בכל זאת \u0003מלמד\u0004 מדבר הנלמד \u0003בקל וחומר כדאמרן\u0004 \u0005[כמו שאמרנו]\u0006 בקטע הקודם, \u0003קל וחומר הלמד מהיקש,\u0004 כמו שהוכחנו \u0003מ\u0004דברי ה\u0003תנא דבי\u0004 \u0005[של בית]\u0006 \u0003ר' ישמעאל\u0004 (לעיל זבחים מא,א), \u0003אינו דין שילמד בקל וחומר?\u0004","ואומרים: \u0003וזהו קל וחומר בן קל וחומר,\u0004 שהרי דין קל וחומר נלמד על ידי קל וחומר אחר. ותוהים: הלוא \u0003בן בנו של קל וחומר הוא,\u0004 שהרי המקור לקל וחומר ממנו למדים כלל זה, שקל וחומר מלמד בגזירה שווה — הוא עצמו נלמד מקל וחומר, כפי שהוכחנו לעיל!","\u0003אלא\u0004 צריך לומר \u0003קל וחומר\u0004 באופן זה: \u0003ומה היקש שאינו למד בהיקש, אי\u0004 \u0005[או]\u0006 \u0003מ\u0004דברי \u0003רבא אי\u0004 \u0005[או]\u0006 \u0003מ\u0004דברי \u0003רבינא,\u0004 בכל זאת \u0003מלמד בקל וחומר מ\u0004מה ששנה ה\u0003תנא דבי\u0004 \u0005[של בית]\u0006 מדרשו של \u0003ר' ישמעאל, קל וחומר\u0004 שהוא עצמו \u0003למד מהיקש, מדתני דבי\u0004 \u0005[ממה ששנה\u0006 התנא \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל, אינו דין שילמד בקל וחומר? וזהו קל וחומר בן קל וחומר.\u0004","ועוד שואלים: \u0003דבר הלמד בקל וחומר, מהו שילמד בבנין אב? אמר ר' ירמיה, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: אם \u0003מלק\u0004 את העוף בקדשים \u0003ונמצאת\u0004 שכבר היתה \u0003טריפה\u0004 ואסורה בהקרבה ובאכילה, \u0003ר' מאיר אומר:\u0004 למרות שלא הוכשרה על ידי המליקה, בכל זאת אין זה נחשב כאילו מתה סתם, ו\u0003אינה מטמאה\u0004 את האדם האוכל אותה כשהיא מצויה \u0003בבית הבליעה\u0004 שלו, כדין נבלת העוף. \u0003ר' יהודה אומר:\u0004 כיון שטריפה היא, והמליקה לא הועילה לה להכשירה — הרי היא נבילה, ולכן \u0003מטמאה בבית הבליעה.\u0004","\u0003אמר ר' מאיר, קל וחומר\u0004 הוא: \u0003ומה נבלת בהמה שמטמאה במגע ובמשא,\u0004 בכל זאת \u0003שחיטתה\u0004 של בהמה \u0003מטהרת\u0004 אפילו את \u0003טריפתה מטומאתה, נבילת עוף\u0004 שדינה קל יותר, \u0003שאין מטמא במגע ובמשא\u0004 אלא רק כשאוכל אותה — \u0003אינו דין שתהא שחיטתה\u0004 של העוף, אם היה זה עוף חולין, \u0003מטהרת טריפתה מטומאתה?\u0004 ומעתה, שלמדנו בקל וחומר, ששחיטתה מטהרת אותה מטומאת נבילה, יש ללמוד בבנין אב: \u0003מה מצינו בשחיטה שמכשרתה באכילה\u0004 אם היה זה עוף חולין, והיא"],["\u0003מטהרת טריפתה מטומאתה, אף מליקה\u0004 בקדשים \u0003שמכשרתה\u0004 את חטאת העוף \u0003באכילה, תטהר טריפתה מטומאתה.\u0004","\u0003ר' יוסי אומר:\u0004 הואיל ומבהמה למדנו עיקרו של דין זה, \u0003דיה\u0004 שתהא טריפת העוף \u0003כנבלת בהמה טהורה, ששחיטתה מטהרתה ולא מליקתה,\u0004 ואין להוסיף לימוד יתר. ועל כל פנים רואים מכאן שר' מאיר לומד בנין אב מקל וחומר.","ודוחים: \u0003ולא היא, התם תיהוי\u0004 \u0005[שם תהיה]\u0006 \u0003היא\u0004 הראיה, במקומה תישאר, ואין ללמוד ממנה, כי במקרה זה \u0003משחיטה דחולין קאתיין\u0004 \u0005[הן באות],\u0006 גם מליקת העוף משחיטת עוף חולין בבנין אב, וגם שחיטת עוף חולין משחיטת בהמת חולין בקל וחומר, ובזה אין הגבלה של למד מלמד.","ועוד שואלים: \u0003דבר הלמד בבנין אב, מהו שילמד בהיקש ובגזירה שוה ובקל וחומר ובבנין אב?\u0004","ואומרים: \u0003פשוט מהא חדא\u0004 \u0005[פתור מאלה אחת]\u0006 ממה ששנינו בברייתא, על רשימת דברים פסולים להקרבה, שאם עלו למזבח — אינם יורדים ממנו בדיעבד, והם: לן, טמא, יוצא, שנשחט חוץ לזמנו, שנשחט חוץ למקומו, שקיבלו פסולים וזרקו את דמו. וכך לשון הברייתא: \u0003מפני מה אמרו: לן בדם\u0004 שהוא \u0003כשר\u0004 כלומר, שאם עלה למזבח לא ירד — \u0003שהרי לן באימורין כשר.\u0004 ומנין אנו יודעים ש\u0003לן באימורין כשר\u0004 — \u0003שהרי לן בבשר כשר\u0004 שהרי בשר שלמים מותר באכילה לכתחילה ליום ולילה ויום.","מנין ש\u0003יוצא\u0004 חוץ לעזרה, אם עלה אין מורידים אותו — \u0003הואיל ויוצא כשר בבמה.\u0004","\u0003טמא\u0004 — \u0003הואיל והותר בעבודת ציבור\u0004 שאם הציבור או הכהנים טמאים הותרה עבודת הציבור בטומאה.","ומנין שקרבן הנפסל במחשבת \u0003חוץ לזמנו\u0004 אם עלה לא ירד — \u0003הואיל ו\u0004הוא \u0003מרצה ל\u0004ענין \u0003פיגולו,\u0004 שהרי אם היה פסול לא היה חל עליו דין פיגול.","\u0003חוץ למקומו\u0004 — \u0003הואיל והוקש לחוץ לזמנו.\u0004","ומה שאמרו על קרבנות \u0003שקיבלו פסולין וזרקו דמן\u0004 שאם אלו לא ירדו — מדובר \u0003בהנך\u0004 \u0005[באותם]\u0006 \u0003פסולין דחזו\u0004 \u0005[שראויים]\u0006 \u0003לעבודת ציבור,\u0004 כגון כהן טמא. על כל פנים למדנו מכאן שדבר הלמד בבנין אב חוזר ומלמד בבנין אב, שהרי לן באימורים נלמד בבנין אב מלן בבשר, וחזר ולימד בבנין אב על לן בדם. ולגופו של לימוד זה שואלים: וכיצד יכול אתה ללמוד על אימורים שאסורים בלינה, מבשר שניתן לכתחילה לאוכלו למחרת? וכיוצא בזה, כיצד אתה למד דינו של יוצא מדין הקרב בבמה בזמן שהיא מותרת?","\u0003וכי דנין דבר שלא בהכשירו\u0004 כלומר, להכשיר דבר שעושה שלא כראוי, \u0003מדבר שבהכשירו\u0004 שכשר כך לכתחילה?","ומשיבים: ה\u0003תנא, מ\"זאת תורת העולה\"\u0004 (ויקרא ו, ב) ש\u0003ריבה\u0004 בה הכתוב את הפסולים שלא ירדו \u0003סמיך ליה\u0004 \u0005[סומך עליה],\u0006 ולא על דרך הלימוד הזאת, שאינה אלא אסמכתא בלבד.","שנינו במשנה: \u0003שירי הדם\u0004 של חטאות הפנימיות, מה שנותר לאחר הזאת הדם, היה שופך על יסוד מערבי של מזבח החיצון, במקום בו הוא בולט מקיר המזבח. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006? \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 לגבי שיירי הדם בפר כהן משיח: \"ואת כל הדם ישפוך \u0003אל יסוד מזבח העלה אשר פתח אהל מועד\"\u0004 (ויקרא ד, ז), לומר \u0003ההוא\u0004 \u0005[אותו\u0006 יסוד\u0005]\u0006 \u0003דפגע ברישא\u0004 \u0005[שפוגש\u0006 אותו \u0005בתחילה]\u0006 כשיוצא מפתח אוהל מועד שהיה במערב.","ובענין זה של שפיכת שיירי דם החטאת נזכר שלוש פעמים \"אל יסוד מזבח העולה\", בפר כהן משיח ובפר העלם דבר שדמם ניתן מתחילה בפנים, ובשעיר נשיא שדמו ניתן בחוץ, ועל כך \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בפר כהן משיח \"ואת כל דם הפר ישפוך \u0003אל יסוד מזבח העלה\"\u0004 (ויקרא ד, ז) הרי זה בא לומר — \u0003ולא\u0004 אל \u0003יסוד מזבח הפנימי\u0004 עליו נזרק דמו, ומה שנאמר שוב בפר העלם דבר:","\u0003\"אל יסוד מזבח העלה\"\u0004 (ויקרא ד, יח), למרות שדינו הושווה לפר כהן משיח, בא לומר כי \u0003אין לו\u0004 כלל \u0003יסוד ל\u0004מזבח \u0003ה\u0004\u0003פנימי עצמו.\u0004","ומה שנאמר שוב בשעיר הנשיא שדמו ניתן על מזבח החיצון: \"ואת דמו ישפוך \u0003אל יסוד מזבח העלה\"\u0004 (ויקרא ד, כה) — בא לומר: \u0003תן יסוד למזבח של עולה\u0004 שכל הדמים הניתנים על מזבח העולה, יישפכו שייריהם אל היסוד.","ויש לשאול: \u0003או אינו אלא\u0004 בא לומר: \u0003מזבחה של עולה יהא ליסוד\u0004 שזריקת דם העולה על קרנות המזבח צריכה להיות במקום שיש בו יסוד למזבח! \u0003אמר ר' ישמעאל:\u0004 אין צורך בכתוב לענין זה, שהרי \u0003קל וחומר\u0004 הוא, \u0003מה שיריים שאין מכפרין,\u0004 בכל זאת \u0003טעונין\u0004 שפיכה במקום \u0003יסוד, תחלת עולה\u0004 כלומר, זריקת דמה על קרנות המזבח, \u0003ש\u0004היא ה\u0003מכפרת, אינו דין שטעונה\u0004 מקום \u0003יסוד?\u0004","ובדומה לכך \u0003אמר ר' עקיבא: מה\u0004 שפיכת \u0003שיריים\u0004 של דם העולה, \u0003שאין מכפרין ואין באין\u0004 מעיקרם \u0003לכפרה\u0004 — \u0003טעונה יסוד, תחלת עולה שמכפרת ובאה לכפרה, אינו דין שטעונה יסוד?\u0004","\u0003אם כן, מה תלמוד לומר \"אל יסוד מזבח העלה\"?\u0004 לומר \u0003תן יסוד למזבחה של עולה.\u0004 עד כאן לשון הברייתא. ומעתה דנים בה לפרטיה.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 נאמר בפר כהן משיח \"ואת כל דם הפר ישפוך \u0003אל יסוד מזבח\u0004 העולה\" (ויקרא ד, ז) — \u0003ולא יסוד מזבח הפנימי.\u0004 ומקשים: \u0003הא מיבעי ליה לגופיה\u0004 \u0005[הרי נזקק\u0006 פסוק זה \u0005לעצמו]\u0006 שצריך לתת שם את שיירי הדם! ומשיבים: דבר זה \u0003מ\"אשר פתח אהל מועד\"\u0004 האמור שם \u0003נפקא\u0004 \u0005[יוצא],\u0006 ומדוע נזכר שהוא מזבח העולה?","ללמד: ולא יסוד מזבח הפנימי. ועוד שנינו בברייתא: \u0003\"אל יסוד מזבח העלה\"\u0004 האמור בשעיר נשיא,"],["בא לומר: \u0003תן יסוד למזבח של עולה,\u0004 כלומר, שיש לשפוך ליסוד את שיירי הדם הנזרק על מזבח העולה.","ומסבירים: \u0003דאי סלקא דעתך כדכתיב\u0004 \u0005[שאם עולה על דעתך\u0006 שבא ללמד \u0005כמו שכתוב],\u0006 \u0003הני\u0004 \u0005[\u0006מקראות \u0005אלה]\u0006 בשעיר נשיא \u0003למה לי קרא\u0004 \u0005[\u0006לכותבם ב\u0005מקרא]\u0006 — \u0003ל\u0004ענין \u0003שירים,\u0004 ללמד שצריך לשפוך על מזבח העולה ולא בפנים, על כך יש לתמוה: וכי צריך לומר זאת לגבי \u0003שירים?\u0004 \u0003הא\u0004 \u0005[הרי]\u0006 את מתנות הדם עצמן \u0003בראי עביד להו\u0004 \u0005[בחוץ\u0006 הוא \u0005עושה אותם],\u0006 ומדוע יעשה את השיריים בפנים?","\u0003וכי תימא דאפיך מיפך\u0004 \u0005[ואם תאמר\u0006 שהיה מקום לומר כן, \u0005ש\u0006הוא \u0005עושה להיפך],\u0006"],["\u0003דבראי לגואי ודגואי לבראי\u0004 \u0005[של ה\u0006ניתנים ב\u0005חוץ\u0006 שופך \u0005בפנים ו\u0006כשם שהוא שופך \u0005של פנים בחוץ]\u0006 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אין לו\u0004 כלל \u0003יסוד ל\u0004מזבח \u0003פנימי עצמו,\u0004 ואיך ניתן לשפוך על יסודו! אלא בא הדבר ללמד על שיירי דם העולה שיישפכו על היסוד. וממשיכים בביאור הברייתא.","ששאלו: \"אל יסוד מזבח העולה\" האמור בשעיר נשיא (ויקרא ד, כה), \u0003או אינו\u0004 בא \u0003אלא\u0004 לומר: \u0003מזבח של עולה יהא ליסוד\u0004 כלומר, שיש לזרוק את דם העולה על קרנות המזבח שיש להן יסוד! ותוהים: כיצד יכול אתה לפרש כן? \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"אל יסוד העולה\"\u0004 שתפרש: אל מקום היסוד יינתן דם העולה? \u0003\"אל יסוד מזבח העלה\" כתיב\u0004 \u0005[נאמר]!\u0006","ומסבירים: גם לפירוש זה שמדובר בזריקת דם העולה, ולא בשפיכת שיריים, יש צורך ב\"מזבח\", שכן \u0003אי הוה כתיב\u0004 \u0005[אם היה נאמר]\u0006 \u0003\"אל יסוד העולה\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003בזקיפה אל\u0004 \u0003יסוד\u0004 שיזרוק את הדם על קיר היסוד, \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003\"אל יסוד מזבח העולה\",\u0004 כוונתו שזורק את הדם על \u0003גגו\u0004 של ה\u0003יסוד\u0004 כלומר מעליו. וממשיכים בביאור הברייתא לדרך זו.","\u0003אמר ר' ישמעאל:\u0004 שיתן את דם העולה על \u0003גג יסוד למה לי קרא\u0004 \u0005[כתוב]\u0006 מפורש? \u0003קל וחומר הוא: ומה\u0004 שפיכת \u0003שירי חטאת\u0004 שנתפרשה בכתוב, \u0003שאינה מכפרת\u0004 — בכל זאת \u0003טעונה גג יסוד, תחלת עולה שמכפרת אינו דין שטעונה גג יסוד?\u0004","\u0003אמר ר' עקיבא\u0004 באופן אחר: \u0003ומה שירי חטאת שאין מכפרין ואין באין לכפר\u0004 בכל זאת \u0003טעונה גג יסוד, תחלת עולה שמכפרת ובאה לכפר אינו דין שטעונה גג יסוד? אם כן, מה תלמוד לומר \"אל יסוד מזבח העלה\"?\u0004 לומר \u0003תן יסוד למזבח של עולה.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין \u0005ר' עקיבא ור' ישמעאל? שלכאורה שניהם אומרים אותו דבר.\u0006 \u0003אמר רב אדא בר אהבה: שירים מעכבים איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 האם כשלא שפכם ליסוד, צריך לחזור וליתן מחדש את כל מתנות הדם, \u0003מר סבר\u0004 \u0005[חכם זה\u0006 ר' ישמעאל \u0005סבור]:\u0006 \u0003מעכבי\u0004 \u0005[מעכבים],\u0006 \u0003ומר\u0004 \u0005[וחכם זה\u0006 ר' עקיבא\u0005],\u0006 שהוסיף ואמר גם: \"ואין באים לכפר\", \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003לא מעכבי\u0004 \u0005[אין מעכבים]\u0006 כלל.","\u0003רב פפא אמר: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003שירים אין מעכבים, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם \u0003מיצוי\u0004 דם \u0003חטאת העוף\u0004 מגופה לאחר הזאת הדם \u0003מעכב קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 שהוא כעין נתינת שיריים לאחר ההזאה, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' ישמעאל, \u0005סבור]:\u0006 \u0003מעכב, ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' עקיבא, \u0005סבור]:\u0006","\u0003לא מעכב. תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב פפא,\u0004 שאף ר' ישמעאל מודה שאין שיריים מעכבים: נאמר בפר כהן משיח \"ואת כל דם הפר ישפך אל יסוד מזבח העולה\" (ויקרא ד, ז) — ויכול היה לכתוב רק \u0003\"ואת כל הדם ישפך\", מה תלמוד לומר \"הפר\"?\u0004 שהרי בפר מדובר בכתוב. אלא \u0003לימד\u0004 על ידי כך \u0003על\u0004 פר אחר, והוא \u0003פר יום הכיפורים ש\u0004גם הוא \u0003טעון מתן דמים ליסוד,\u0004 אלו \u0003דברי רבי.\u0004","\u0003אמר ר' ישמעאל:\u0004 זה אינו צריך לכתוב מיוחד, אלא \u0003קל וחומר\u0004 הוא: \u0003ומה אם מי שאין נכנס דמו לפנים חובה\u0004 כלומר, פר כהן משיח, שאינו חובה קבועה, אלא שאם חטא הכהן צריך להביא פר זה — בכל זאת \u0003טעון יסוד, מי שנכנס דמו לפנים חובה\u0004 כלומר, פר יום הכיפורים, שהוא חובה קבועה לישראל \u0003—\u0004 \u0003אינו דין שטעון יסוד?\u0004","וכן \u0003אמר ר' עקיבא\u0004 באופן אחר: \u0003ומה מי שאין דמו נכנס לפני ולפנים\u0004 כלומר, פר כהן משיח, שאין מכניסים את דמו כלל לקודש הקדשים, \u0003בין לחובה\u0004 קבועה \u0003בין למצוה\u0004 מזדמנת — בכל זאת \u0003טעון יסוד, מי שנכנס דמו חובה לפני ולפנים\u0004 כלומר, פר יום הכיפורים, \u0003אינו דין שטעון יסוד?\u0004 ואם כן, לא לשם כך הוצרך \"הפר\" המיותר, ללמדנו שפר יום הכיפורים טעון יסוד.","\u0003יכול\u0004 בא הדבר להדגיש דין זה ולומר שמתן שיריים ליסוד \u0003יעכבנו\u0004 את הקרבן? \u0003תלמוד לומר\u0004 בעבודת יום הכיפורים, לאחר הזאת הדם בהיכל: \u0003\"וכלה מכפר את הקדש\"\u0004 (ויקרא טז, כ), לומר שלאחר מתן דמים בפנים \u0003שלמו כל הכפרות כולן,\u0004 אלו \u0003דברי ר' ישמעאל.\u0004","ולפי דרך זו של קל וחומר, יש לדרוש גם \u0003קל וחומר לפר כהן משיח משעיר נשיא מעתה: ומה\u0004 שעיר נשיא, \u0003מי שאין נכנס דמו לפנים לא\u0004 בגדר \u0003חובה\u0004 קבועה \u0003ולא\u0004 בגדר \u0003מצוה,\u0004 והוא מוקרב כשאר חטאות היחיד על המזבח החיצון — \u0003טעון יסוד\u0004 (ויקרא ד, כה), פר כהן משיח, \u0003מי שנכנס דמו לפנים בין לחובה בין למצוה, אינו דין שטעון יסוד?\u0004 ואם כן מתן יסוד שנאמר בו מיותר.","\u0003יכול יעכבנו?\u0004 כלומר, שמא בא ללמד שיהא בזה עיכוב לפר כהן משיח אם לא שפך שיירי הדם? \u0003תלמוד לומר\u0004 לאחר שנאמר בו \"ונתן מן הדם\" וכו' — \u0003\"ואת כל הדם ישפך\"\u0004 (ויקרא ד, ז), ומתוך שלא השתמש הכתוב בלשון \"ושפך את כל הדם\", כהמשך לאמור קודם —","\u0003נתקו הכתוב לעשה\u0004 זה מן הציוויים הקודמים, \u0003ועשאו שירי מצוה,\u0004 לומר שאינו חלק מעיקר המצוה. ובכך בא \u0003לומר לך: שירים אין מעכבין.\u0004 ומכאן ראיה לדברי רב פפא, שאף לדעת ר' ישמעאל שיריים אינם מעכבים. ולכן פירש שנחלקו במיצוי חטאת העוף.","ושואלים: \u0003ו\u0004כי \u0003סבר ר' ישמעאל מיצוי חטאת העוף מעכב\u0004 כפי שהסביר רב פפא? \u0003והתנא דבי\u0004 \u0005[והרי שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 על הכתוב בחטאת העוף \"והזה מדם החטאת על קיר המזבח \u0003והנשאר בדם ימצה\u0004 אל יסוד המזבח\" (ויקרא ה, ט) — \u0003והנשאר ימצה\u0004 כלומר, אם נשאר דם — ימצה,"],["\u0003ושאינו נשאר לא ימצה\u0004 כלומר, אם לא נותר דם לאחר ההזאה — אינו צריך למצות. משמע שאין המיצוי מעכב! ומשיבים: \u0003תרי תנאי\u0004 \u0005[שני תנאים\u0006 הם\u0005]\u0006 \u0003ו\u0004חלוקים \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' ישמעאל.\u0004","ועוד בענין שיריים האם הם מעכבים, \u0003אמר רמי בר חמא: האי תנא\u0004 \u0005[תנא זה]\u0006 \u0003סבר: שירים מעכבי\u0004 \u0005[מעכבים],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 לגבי האמור בחטאת: \u0003\"הכהן המחטא אותה\u0004 יאכלנה\" (ויקרא ו, יט), \"אותה\" בא להדגיש ולמעט: \u0003אותה שניתן דמה\u0004 כראוי \u0003למעלה\u0004 מחוט הסיקרא שבמזבח — כשירה היא, ויאכל הכהן את בשרה, \u0003ולא אותה שניתן דמה למטה.\u0004","וממשיכה הברייתא, \u0003אמרת\u0004 אומר אתה בענין זה: \u0003וכי מאין באתה?\u0004 כלומר, מה מקום היה להכשיר באופן זה, שהוצרך בכתוב להדגיש שהיא נפסלת בכך? ומסבירים: \u0003מכלל שנאמר: \"ודם זבחיך ישפך על מזבח\u0004 ה' אלוקיך והבשר תאכל\" (דברים יב, כז), \u0003למדנו ל\u0004כל הדמים \u0003הניתנים\u0004 על מזבח העולה, גם דמי חטאת הניתנים \u0003במתן ארבע, שאם נתנן במתנה אחת\u0004 — \u0003כיפר.\u0004 ולפיכך, כיוון שמצאנו שגם אם שינה מן האמור בכתוב כיפר, \u0003יכול אף הניתנין למעלה שנתנן למטה\u0004 גם הוא \u0003כיפר? ו\u0004לכאורה","\u0003דין הוא\u0004 שלא יכפר, שהרי \u0003נאמרו דמים למעלה\u0004 בזריקת דם חטאת בהמה, שנותן על הקרנות למעלה מחצי המזבח (חוט הסיקרא), \u0003ונאמרו דמים למטן\u0004 בחטאת העוף, שדמה ניתן על חלקו התחתון של קיר המזבח, \u0003מה דמים האמורים למטן שנתנן למעלן לא כיפר,\u0004 כפי שלמדו חכמים מן ההדגשה בחטאת העוף \"חטאת הוא\" (ויקרא ה, ט) — לעכב, \u0003אף דמים האמורים למעלן אם נתן למטה לא כיפר!\u0004","ויש לדחות: \u0003לא, אם אמרת בתחתונים\u0004 (דמי חטאת העוף) \u0003שניתנין בנתינה למעלה\u0004 שלא כיפר, \u0003ש\u0004הרי \u0003אין סופן\u0004 להיות ניתנים \u0003למעלן\u0004 כלל, ולכן סברה היא שאם שינה מקומם \u0003לא כיפר, תאמר בעליונים\u0004 (דמי חטאת בהמה) \u0003שנתנן למטה\u0004 שלא כיפר? והרי שם שונה הדבר, \u0003שיש מהן קרב למטה,\u0004 כששופך את השיריים ליסוד, ויש לומר שגם אם נתן בתחילה למטה — כיפר!","ומשיבים: \u0003דמים הפנימיים\u0004 של החטאות שדמן ניתן בהיכל \u0003יוכיחו, שיש מהן קרב בחוץ,\u0004 שהרי נאמר בתורה שאת שייריהן שופך על יסוד המזבח החיצון, \u0003ו\u0004למרות זאת \u0003אם נתנן בתחלה בחוץ לא כיפר!\u0004","ודוחים: \u0003לא, אם אמרת בדמים הפנימיים,\u0004 שיש בהם חומרה יתירה, \u0003שאין מזבח הפנימי ממרקן\u0004 כלומר, אינו גומר את עבודתן, וצריכים לעבודה אחרת, \u0003תאמר בעליונים\u0004 (דם חטאת בהמה חיצונה) \u0003שהרי קרנות ממרקות אותן\u0004 ונגמרה בכך עבודתן, ולכן אפשר היה לומר ש\u0003אם נתנן למטה כשרים!\u0004","\u0003תלמוד לומר\u0004 בחטאת בהמה חיצונה \u0003\"אותה\",\u0004 להדגיש: \u0003אותה שניתן דמים למעלה\u0004 כשירה, \u0003ולא שניתן דמה למטה.\u0004 עד כאן בברייתא, ומכאן ממשיך רמי בר חמא להוכיח את דבריו.","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 מה שנאמר לגבי דמים הפנימיים \u0003שאין מזבח הפנימי ממרקן? לאו\u0004 \u0005[האם לא]\u0006 \u0003אלו שיריים,\u0004 שלא נגמרה נתינת הדמים הפנימיים במתן הדמים על המזבח הפנימי, אלא רק לאחר שפיכת השיריים על יסוד המזבח החיצון? משמע מכאן ששיריים (של חטאות הפנימיות) מעכבים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אי הכי\u0004 \u0005[אם כך],\u0006 שלפי ברייתא זו שיריים מעכבים, מדוע יש צורך בכתוב ללמדנו דין זה, שעליונים שנתנן למטה לא כיפר? \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 \u0003בקל וחומר:\u0004","\u0003מה שיריים הפנימיים שסופן חובה בחוץ\u0004 (שהם מעכבים) בכל זאת אם \u0003עשאן\u0004 את הדמים הפנימיים \u0003בתחלה בחוץ לא כיפר,\u0004 \u0003הניתנין למעלה שאין סופן חובה\u0004 לרדת \u0003למטה\u0004 (שהרי שיירי מזבח החיצון בוודאי אינם מעכבים) \u0003ועשאן בתחלה למטה, אינו דין שלא כיפר?\u0004 וכיון שלא נאמרה סברה זו בברייתא, והוצרכנו ללמוד דין זה מן הכתובים, משמע ששיריים אינם מעכבים.","\u0003אלא\u0004 לכך הכוונה: דמים הפנימיים \u0003אין מזבח הפנימי ממרקן בלבד, אלא\u0004 גם מתן הדמים על גבי \u0003פרוכת,\u0004 ומשום כך חמור דינם, ואין ללמוד מכאן לדמים העליונים של מזבח החיצון.","ועוד לענין שיריים מעכבים, מביאים ברייתא אחרת. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בעבודת יום הכיפורים לאחר הזאות הדם בפנים: \u0003\"וכלה מכפר\u0004 את הקדש\" (ויקרא טז, כ), ויש לדייק מכאן: \u0003אם כיפר\u0004 שנתן כל ההזאות בפנים — \u0003כלה\u0004 בכך את עבודת הפר והשעיר הפנימיים, \u0003ואם לא כיפר\u0004 — \u0003לא כלה, דברי ר' עקיבא. אמר לו ר' יהודה, מפני מה לא נאמר\u0004 ונדרוש כך את הכתוב: \u0003אם כלה\u0004 ונתן את כל מתנות הדם — \u0003כיפר, אם לא כלה\u0004 — \u0003לא כיפר,\u0004 ומכאן נלמד \u0003שאם חיסר אחת מכל המתנות לא עשה ולא כלום?\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]?\u0006 שלכאורה שניהם אומרים דבר אחד! \u0003ר' יוחנן ור' יהושע בן לוי\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: משמעות דורשין איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 כלומר, שההבדל ביניהם אינו להלכה, שלשיטת שניהם דורשים מכאן כי המתנות שבפנים מעכבות, אלא בדרך הדרשה. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 מחלוקת לגבי \u0003שיריים מעכבין איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שלדעת ר' עקיבא אין השיריים מעכבים, וכיון שכיפר בפנימיים — כילה את העבודה. ואילו לדעת ר' יהודה, רק אם כילה הכל (ובכלל זה שפיכת שיירי הדם על היסוד) — כיפר.","ומציעים: \u0003תסתיים\u0004 \u0005[תוגדר,\u0006 תוחלט\u0005]\u0006 ש\u0003ר' יהושע בן לוי הוא\u0004 ש\u0003אמר שיריים דמעכבי\u0004 \u0005[שמעכבים]\u0006 יש ביניהם, ש\u0003אמר ר' יהושע בן לוי: לדברי האומר שיריים מעכבין,\u0004 אם גמר את מתן הדמים בפנים ונשפך הדם, ולא הספיק לשפוך את השיריים בחוץ, \u0003מביא פר אחד\u0004 ושוחטו \u0003ומתחיל\u0004 בהזאות \u0003בתחלה בפנים\u0004 על מנת שיהו שיריים, ואחר כך ישפוך השיריים על יסוד המזבח החיצון.","ודוחים ראיה זו: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003ר' יוחנן לית ליה הא סברא\u0004 \u0005[אין לו סברה זו]\u0006 שיש מי שסבור ששיריים מעכבים? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: תנא\u0004 \u0005[שנה]\u0006 \u0003ר' נחמיה כדברי האומר שירים מעכבין!\u0004 הרי שגם הוא סבור שיש מי שאומר כן.","\u0003אלא\u0004 אין להוכיח מכאן את דעתו לגבי מחלוקת זו, משום שהוא אומר בצורה סתמית \u0003\"כדברי האומר\" ו\u0004יש להסביר כי \u0003לאו להני תנאי\u0004 \u0005[לא ל\u0006מחלוקת \u0005תנאים אלה]\u0006 הוא מתכוון, שאולי שניהם סבורים שאין שיריים מעכבים. אם כן, \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 בדברי ר' יהושע בן לוי, אפשר להבין שגם הוא אומר \u0003כדברי האומר ולאו להני תנאי\u0004 \u0005[ולא ל\u0006מחלוקת \u0005תנאים אלה].\u0006 ואם כן, אין להוכיח מכאן מיהו הסובר שר' יהודה אומר ששיריים מעכבים.","ומעתה דנים איזהו מקומן של \u0003חטאות הצבור והיחיד.\u0004 ותחילה מגדירים: \u0003אלו הן חטאות הצבור\u0004 בהן אנו עוסקים בהלכה זו: \u0003שעירי\u0004 חטאת שמקריבים עם מוספי \u0003ראשי חדשים\u0004 (במדבר כח, טו), \u0003ו\u0004כן שעירים \u0003של מועדות\u0004 (ראה במדבר כח, כב, ל ועוד). כל אלו \u0003שחיטתן בצפון, וקיבול דמן בכלי שרת בצפון, ודמן טעון ארבע מתנות\u0004 (נתינות) הזאות \u0003על ארבע קרנות\u0004 של המזבח. \u0003כיצד\u0004 עושה?"],["\u0003עלה בכבש\u0004 של המזבח \u0003ופנה\u0004 ימינה \u0003לסובב\u0004 ושם היה מהלך לכיוון מזרח, \u0003ו\u0004כך \u0003בא לו\u0004 תחילה \u0003לקרן דרומית מזרחית\u0004 ונותן עליה באצבעו מדם החטאת עליה, אחר כך לקרן \u0003מזרחית צפונית\u0004 ונותן שם מתנה שניה, וכן \u0003צפונית מערבית, מערבית דרומית,\u0004 ומשם ירד מן המזבח. \u0003שירי הדם\u0004 שבמזרק \u0003היה שופך על יסוד דרומית\u0004 (שמדרום למזבח). \u0003ונאכלין\u0004 חלקי הבשר של החטאת \u0003לפנים מן הקלעים\u0004 (בתוך העזרה), \u0003לזכרי כהונה\u0004 בלבד, ונאכלים \u0003בכל מאכל\u0004 כלומר, יכול להתקינם לאכילה בכל דרך שרוצה, \u0003ליום ולילה עד חצות\u0004 הלילה.","ומבררים: \u0003היכי עביד\u0004 \u0005[כיצד\u0006 הוא \u0005עושה]\u0006 בהזאת דם החטאת בקרנות? \u0003ר' יוחנן ור' אלעזר\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: נותן אמה אילך ואמה אילך,\u0004 יכול להזות את הדם במרחק של אמה לכל צד, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: מחטא\u0004 (מזה) \u0003ויורד כנגד חודו של קרן.\u0004","ואומרים: \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' אלעזר בר' שמעון\u0004 ש\u0003אמר: היא,\u0004 הזאת החטאת \u0003עצמה אינה נעשית אלא בגופה של קרן\u0004 כלומר, באותו מבנה בן אמה על אמה המצוי בראש כל אחת מן הקרנות, \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שאין צורך שיזה דווקא על חודה של קרן, שהרי בכל אופן הוא מקיים את הציווי \"ונתן על קרנות מזבח העולה\" (ויקרא ד, כה). \u0003כי פליגי\u0004 \u0005[כאשר חלוקים\u0006 הם\u0005]\u0006 הרי זה \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003רבי,\u0004 שהבין כי הקרן המוזכרת בתורה משמעה — זוית המזבח (בחציו העליון), \u0003מר סבר\u0004 \u0005[חכם זה סבור]:\u0006 \u0003אמה אילך ואמה אילך\u0004 הזאה \u0003כנגד קרן הוא\u0004 נחשב, \u0003ומר סבר\u0004 \u0005[וחכם זה סבור]:\u0006 הזאה \u0003כנגד חודה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 היא נחשבת הזאה על הקרן, \u0003טפי\u0004 \u0005[יותר\u0006 מכאן\u0005]\u0006 — \u0003לא.\u0004","על דעת הסבור שניתן לתת אמה הילך ואמה הילך, \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא: \u0003חטאת הציבור והיחיד כיצד מתן דמן? היה עולה לכבש ופנה לסובב ובא לו לקרן דרומית מזרחית, וטובל באצבעו הימנית,\u0004 ואיזו היא — אצבע \u0003המיומנת שבימין\u0004 כלומר, זו שאדם משתמש בה יותר מן האחרות, והיא הסמוכה לאגודל, \u0003מן הדם שבמזרק, וחומר\u0004 (אוסף) \u0003בגודלו מלמעלה ובאצבעו קטנה מלמטה, ומחטא\u0004 (מזה) \u0003ויורד כנגד חודה של קרן עד שמכלה כל הדם שבאצבע, וכן\u0004 היה עושה ב\u0003כל קרן וקרן.\u0004 הרי שצריך שיזה על חודה של קרן!","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003מצוה\u0004 לכתחילה \u0003בחודה,\u0004 אבל \u0003אי עבד\u0004 \u0005[אם עשה]\u0006 \u0003אמה אילך ואמה אילך לית לן\u0004 \u0005[אין לנו]\u0006 לפקפק \u0003בה,\u0004 אלא גם בזה מתקיימת המצוה.","הזכרנו שיש מחלוקת תנאים בדבר, ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 שיטתו של \u0003רבי, ומאי\u0004 \u0005[ומהי]\u0006 שיטתו של \u0003ר' אלעזר בר' שמעון? דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003דמים העליונים\u0004 שמצוה לתיתם בחצי המזבח העליון, כגון דם החטאת — \u0003ניתנין מחוט הסיקרא\u0004 (פס של צבע אדום) שהיה באמצעו של המזבח \u0003ולמעלה, דמים התחתונים ניתנין מחוט הסיקרא ולמטן,\u0004 אלו \u0003דברי רבי.\u0004","\u0003ר' אלעזר בר' שמעון אומר: במה דברים אמורין\u0004 — \u0003בעולת העוף,\u0004 שיכול לעשות אותה בכל מקום למעלה מחוט הסיקרא, \u0003אבל בחטאת בהמה\u0004 — \u0003היא עצמה אין נעשית\u0004 מצותה \u0003אלא על גופה של קרן,\u0004 כפי שהוזכר בתורה \"על קרנות מזבח העולה\" (ויקרא ד, כה).","\u0003אמר ר' אבהו: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי,\u0004 שדמים עליונים ניתנים מחוט הסיקרא ולמעלה? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לגבי המזבח: \u0003\"וההראל\u0004 (המזבח) \u0003ארבע אמות, ומהאראיל ולמעלה\u0004 הקרנות ארבע\" (יחזקאל מג, טו), ותוהים: וכי גובה הקרנות \u0003ארבע אמות הוא דהויא\u0004 \u0005[הן]?\u0006 \u0003אמר רב אדא בר אהבה:\u0004 הכוונה היא — \u0003ומקום קרנות ארבע\u0004 שזהו שטחן הכולל של קרנות המזבח, ארבע על ארבע אמות. ותוהים: \u0003ו\u0004כי \u0003מקום קרנות ארבע הויא\u0004 \u0005[הוא]?\u0006 והרי אם שטחה של כל קרן הוא אמה על אמה, נמצא ששטחן הכולל הוא שתי אמות מרובעות! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003רשות קרנות ארבע\u0004 כלומר, שבתוך ארבע אמות מן הקרן ולמטה הריהו נחשב בגדר הקרן, ובכל תחום זה ניתן להזות מדם החטאת.","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 במסכת מדות: \u0003חוט של סיקרא חוגרו\u0004 את המזבח \u0003באמצע, להבדיל בין דמים העליונים לדמים התחתונים.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רב אחא בר רב קטינא, שנאמר: \"והיתה הרשת עד חצי המזבח\"\u0004 (שמות כז, ה), הרי ש\u0003התורה נתנה מחיצה\u0004 במזבח, ולשם מה נעשה הדבר — \u0003להבדיל בין דמים העליונים לדמים התחתונים.\u0004 ורשת זו היתה רק במזבח שבמשכן, אבל במקדש עשו חוט של סיקרא כסימן.","שנינו במשנה: \u0003שירי הדם\u0004 של חטאת חיצונה היה שופך על יסוד דרומי. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \"ואת כל דמה ישפוך \u0003אל יסוד\u0004 ה\u0003מזבח\"\u0004 (ויקרא ד, לד) — \u0003זה יסוד דרומי. אתה אומר: זה יסוד דרומי, או אינו אלא יסוד מערבי,\u0004","\u0003וילמד סתום מן המפורש,\u0004 שהרי נאמר בחטאות הפנימיות ששופך את דמן על היסוד המערבי, שהוא בפתח אוהל מועד (ראה לעיל זבחים נא,א)! \u0003אמרת\u0004 בתשובה לכך: \u0003ילמד ירידתו מן הכבש\u0004 (לאחר ההזאה על מזבח החיצון) \u0003ליציאתו מן ההיכל\u0004 במתן דמים פנימיים, \u0003מה\u0004 ב\u0003יציאתו מן ההיכל\u0004 שופך את השיריים \u0003בסמוך לו,\u0004 והוא יסוד מערבי, \u0003אף ירידתו מן הכבש\u0004 שופך \u0003בסמוך לו,\u0004 והיסוד הסמוך לירידתו מן הכבש הוא יסוד דרומי.","ועוד בענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' ישמעאל אומר: זה וזה,\u0004 הן שיירי הדמים הפנימיים והן שיירי הדמים החיצוניים, שופך ל\u0003יסוד מערבי. ר' שמעון בן יוחאי אומר: זה וזה\u0004 ל\u0003יסוד דרומי.\u0004","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 \u0003יסוד מערבי\u0004 — \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003ילמד סתום מן המפורש,\u0004 וכיון שמפורש ששיירי חטאות הפנימיות ניתנים ביסוד מערבי, אף חטאות החיצוניות ביסוד מערבי.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי גם שיירי הדמים הפנימיים ניתנים על \u0003יסוד דרומי, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר רב אסי, קסבר האי תנא\u0004 \u0005[סבור תנא זה]:\u0006 \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003מזבח בצפון\u0004 העזרה \u0003קאי\u0004 \u0005[עומד],\u0006 כך שקצהו הדרומי נמצא בדיוק מול מרכז פתח ההיכל, ולכן יסוד דרומי הוא הסמוך ביותר לפתח ההיכל, ומתקיים בו \"פתח אוהל מועד\". \u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 על אותו ענין, באותה משמעות: \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003פתח בדרום קאי\u0004 \u0005[עומד],\u0006 וכשיוצא ממנו נותן את הדם בסמוך ליסוד דרומי."],["\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004 בשם \u0003ר' שמעון בן יוחי,\u0004 שהיו \u0003אומרים\u0004 בשמו: \u0003זה וזה יסוד מערבי,\u0004 כשיטת ר' ישמעאל. \u0003וסימניך\u0004 כדי לזכור את השיטה: \u0003משכו גברי לגברא\u0004 \u0005[אנשים לאיש]\u0006 שתלמידי ר' ישמעאל (שהם רבים), משכו את שיטת ר' שמעון לומר כדברי רבם.","\u0003העולה קדשי קדשים\u0004 היא, וכך דרך עבודתה: \u0003שחיטתה בצפון, וקיבול דמה בכלי שרת בצפון, ודמה טעון שתי מתנות\u0004 (נתינות) \u0003שהן ארבע\u0004 בשתי זויות המזבח, בקרן מזרחית צפונית ובקרן מערבית דרומית, כך שהדם ניתן על ארבעה צדדיו, כאשר יבואר בגמרא. \u0003ו\u0004לענין הקרבתה על המזבח, הריהי \u0003טעונה\u0004 (צריכה) תחילה \u0003הפשט\u0004 של העור \u0003וניתוח\u0004 הבשר לחלקים, \u0003ו\u0004כולה נשרפת \u0003כליל לאשים\u0004 על אש המזבח (חוץ מן העור, הניתן לכהנים).","ומעירים: \u0003עולה מאי טעמא תני ליה\u0004 \u0005[מה הטעם שונה בה]\u0006 שהיא \u0003קדשי קדשים,\u0004 ולא אמר כן בחטאת במשנה הקודמת (לעיל זבחים נב,ב)? \u0003משום\u0004 ש\u0003לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה\u0004 בתורה \u0003\"קדשי קדשים היא\"\u0004 כמו שכתוב בחטאת.","שנינו במשנה: \u0003ודמה טעון שתי מתנות\u0004 שהן ארבע. ושואלים: \u0003היכי עביד\u0004 \u0005[כיצד\u0006 הוא \u0005עושה]\u0006 בדיוק? \u0003אמר רב:\u0004 כגון בקרן מזרחית צפונית \u0003נותן\u0004 מתנה אחת בצד מזרח של זוית המזבח \u0003וחוזר ונותן\u0004 מתנה בצד צפון של אותה זוית, וכן בזוית שמולה באלכסון, בקרן מערבית דרומית. \u0003ושמואל אמר: מתנה אחת כמין\u0004 צורת אות \u0003גמא\u0004 (זוית) \u0003נותן\u0004 שזורק את הדם על חוד המזבח, והוא מתפשט בזוית לשני הצדדים.","ומעירים: ומחלוקת זו \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים\u0006 היא\u0005]\u0006 ששנינו: \u0003יכול יזרקנו\u0004 את דם העולה \u0003זריקה אחת? תלמוד לומר:\u0004 \"וזרקו את הדם על המזבח \u0003סביב\"\u0004 (ויקרא א, ה). \u0003אי\u0004 \u0005[אם]\u0006 \u0003סביב, יכול יקיפנו כחוט? תלמוד לומר: \"וזרקו\"\u0004 ובזריקה אינו יכול לעשות חוט של דם סביב, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד?\u0004 נותן \u0003כמין גמא, שתי מתנות שהן ארבע.\u0004 והוא כדברי שמואל.","\u0003ר' ישמעאל אומר: נאמר כאן\u0004 בעולה: \u0003\"סביב\",\u0004 שצריך לתת על ארבעה צידי המזבח, \u0003ונאמר להלן\u0004 בחטאת: \u0003\"סביב\"\u0004 (ויקרא ח, טו), \u0003מה להלן\u0004 בחטאת, מדובר ב\u0003פיסוק\u0004 וארבע מתנות שצריך לתת את הדם על כל אחת מארבע הקרנות — \u0003אף כאן\u0004 בעולה \u0003פיסוק וארבע מתנות.\u0004","ויש לשאול: \u0003אי מה להלן\u0004 בחטאת \u0003ארבע מתנות על ארבע קרנות\u0004 על כל אחת מהן, \u0003אף כאן\u0004 בעולה יצטרך לתת \u0003ארבע מתנות על ארבע קרנות!\u0004 על כך \u0003אמרת\u0004 אומר אתה בתשובה: \u0003עולה טעונה\u0004 מתן דמים דווקא במקום שיש בו \u0003יסוד, וקרן מזרחית דרומית\u0004 של המזבח \u0003לא היה לה יסוד,\u0004 ולפיכך מתחיל בקרן המזרחית צפונית, וזורק שם את הדם תחילה בצידה המזרחי של הקרן, ואחר בצידה הצפוני.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שלא היה יסוד לקרן דרומית מזרחית? \u0003אמר ר' אלעזר: לפי שלא היתה בחלקו של טורף,\u0004 כלומר, לא היתה בחלקו של שבט בנימין, שנתנבא עליו יעקב \"בנימין זאב יטרף\" (בראשית מט, כז), שבחלקו יימצא המזבח, אלא בחלקו של יהודה, וכפי ש\u0003אמר רב שמואל בר רב יצחק: מזבח אוכל\u0004 נכנס \u0003בחלקו של יהודה אמה\u0004 אחת, והיא האמה שבה היתה קרן מזרחית דרומית של המזבח.","ואותה אמה היא זו ש\u0003אמר ר' לוי בר חמא אמר ר' חמא בר' חנינא: רצועה היתה יוצאה מחלקו של יהודה ונכנסה בחלקו של בנימין, והיה בנימין הצדיק מצטער עליה בכל יום לנוטלה,\u0004 שגם היא תהיה בחלקו, \u0003שנאמר\u0004 בברכת משה לבנימין:"],["\u0003\"חפף עליו כל היום\"\u0004 (דברים לג, יב), שדורשים כתוב זה כאילו היה חופף = מחכך בראשו מחמת דאגה וצער, שהיה רוצה שיהיה בחלקו, \u0003לפיכך,\u0004 משום שהיה כל כך דואג לכך, \u0003זכה בנימין הצדיק ונעשה אושפיזכן\u0004 (מארח) \u0003להקדוש ברוך הוא, שנאמר: \"ובין כתפיו שכן\"\u0004 (דברים לג, יב), לומר שמקום קודש הקדשים היה דווקא בחלקו של בנימין.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על מה שאמרו שלא היה יסוד בקרן דרומית מזרחית, ממה ששנינו: \u0003עולת העוף\u0004 שהיתה נעשית בקרן זו \u0003כיצד היתה נעשית? היה\u0004 עומד על הסובב ו\u0003מולק את ראשה ממול עורפה, ומבדיל\u0004 את הראש מן הגוף, \u0003ו\u0004כשהוא אוחז בגוף \u0003ממצה דמה\u0004 כשהוא דוחק את הצואר \u0003על קיר המזבח.\u0004","\u0003ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 ש\u0003לא היה לה\u0004 לאותה קרן \u0003יסוד,\u0004 נמצא שאת עבודתה, שהוא עושה כשהוא עומד על הסובב — \u0003באוירא בעלמא\u0004 \u0005[באויר בלבד]\u0006 \u0003הוא דקא עביד\u0004 \u0005[שעושה]\u0006 ולא מעל מקום המזבח! \u0003אמר רב נחמן בר יצחק, אימר\u0004 \u0005[אמור]\u0006 ש\u0003כך התנו: אוירא\u0004 \u0005[האויר]\u0006 של מקום היסוד היה בחלקו של \u0003בנימין,\u0004 וכך נעשית עבודתה בתחום המזבח, אבל ה\u0003קרקע\u0004 היתה בחלקו של \u0003יהודה,\u0004 ולכן לא היה שם יסוד.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 מה שנאמר בברייתא \u0003לא הוא\u0004 \u0005[היה]\u0006 \u0003לה יסוד\u0004 לקרן דרומית מזרחית? \u0003רב אמר: בבנין,\u0004 שלא נבנה שם היסוד. \u0003לוי אמר: בדמים\u0004 כלומר, אף שהיה שם יסוד, הואיל והיה בחלקו של יהודה — לא היה לו דין של יסוד המזבח, לענין מתן דמים. ולפי שיטתם נחלקו בתרגום ברכתו של יעקב בפסוק \"בנימין זאב יטרף\" (בראשית מט, כז), שלפי המסורת מתארת את נחלתו של בנימין, \u0003רב\u0004 היה \u0003מתרגם: באחסנתיה יתבני מדבחא\u0004 \u0005[בנחלתו יבנה המזבח],\u0006 שעליו היו הקרבנות \"נטרפים\", ולא בנחלת שבט אחר. \u0003לוי\u0004 היה \u0003מתרגם\u0004 את הפסוק: \u0003באחסנתיה יתבני מקדשא\u0004 \u0005[בנחלתו יבנה המקדש],\u0006 כלומר, \u0003מקום מקודש לדמים,\u0004 שאף שלא כל המזבח בנוי בחלקו, מכל מקום רק בחלקו מזים ושופכים את דם הקרבנות. ומביאים ראיות לכאן ולכאן.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בתיאור המזבח שבמסכת מדות: \u0003היסוד היה מהלך על פני כל\u0004 קיר \u0003הצפון\u0004 של המזבח \u0003ועל פני כל המערב, אוכל\u0004 כלומר, תופס \u0003בדרום\u0004 המזבח \u0003אמה אחת ובמזרח אמה אחת,\u0004 משמע שחוץ מאותה אמה שבדרום ושבמזרח לא היה שם יסוד בנוי, וכדברי רב! ודוחים: אפשר לפרש כי \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003אוכל? נמי\u0004 \u0005[גם כן]\u0006 \u0003בדמים,\u0004 שלא היו מזים שם את דם העולה.","ומביאים ראיה לצד האחר, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו באותה משנה: \u0003המזבח היה שלשים ושתים על שלשים ושתים\u0004 אמה, משמע שהיה יסוד בכל צד, וכדברי לוי, שהרי היסוד נכלל באותן שלושים ושתים אמה! ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003מן הצד,\u0004 כלומר, שמצד צפון וצד מערב היה שלושים ושתים על שלושים ושתים, אבל לא היה בנוי כולו כך.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה שהיה שם יסוד, ממה ששנינו בברייתא: \u0003נמצא\u0004 הכבש הבנוי בדרום המזבח, וצריך שיגיע בקצהו לראש המזבח \u0003פורח\u0004 (עולה) ברוחב \u0003אמה\u0004 מ\u0003על\u0004 ה\u0003יסוד\u0004 וברוחב \u0003אמה\u0004 מ\u0003על\u0004 ה\u0003סובב.\u0004 משמע שהיה יסוד! ודוחים: \u0003אימא\u0004 \u0005[אמור]\u0006 כך: \u0003כנגד,\u0004 כלומר, במקום בו היתה ראויה להיות \u0003אמה יסוד,\u0004 אף שבפועל לא היה שם יסוד, \u0003ועל אמה סובב.\u0004","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003לוי\u0004 בברייתא שהיתה בידו: \u0003כיצד בונין את המזבח? מביאין\u0004 תחילה \u0003מלבן\u0004 (מסגרת של קרשים) \u0003שהוא\u0004 באורך \u0003שלשים ושתים\u0004 אמה \u0003על\u0004 רוחב \u0003שלשים ושתים, וגובהו אמה\u0004 אחת, \u0003ומביא חלוקי אבנים מפולמות\u0004 (לחות) \u0003בין\u0004 שהיו \u0003גדולות בין\u0004 שהיו \u0003קטנות,\u0004 שהן עיקרו של המזבח (\"מזבח אבנים\"), וממלא בהם את המלבן. \u0003ומביא סיד וקוניא\u0004 (סיגים של עופרת) \u0003וזפת, וממחה,\u0004 כלומר, מתיך אותם יחד, \u0003ושופך\u0004 את התערובת על חלוקי האבן להדביקם בו. \u0003וזה הוא מקום יסוד.\u0004","\u0003וחוזר ומביא מלבן שהוא שלשים אמה על שלשים אמה וגובהו חמש אמות,\u0004 ומניחו על היסוד, \u0003ומביא חלוקי אבנים\u0004 מפולמות ו\u0003כו'\u0004 ומביא סיד וקוניא וזפת וכו', וכך נוצר הסובב\u0003.\u0004 \u0003וחוזר ומביא מלבן שהוא עשרים ושמונה על עשרים ושמונה אמות וגובהו שלש אמות,\u0004 ומניחו על החלק השני, \u0003ומביא חלוקי\u0004 אבנים ו\u0003כו', והוא מקום המערכה.\u0004","\u0003וחוזר ומביא מלבן שהוא אמה על אמה, ומניחו באחת מזויות המזבח, ומביא חלוקי אבנים מפולמות בין גדולות בין קטנות, ומביא זפת וקוניא וממחה ושופך, וזהו\u0004 ה\u0003קרן. וכן\u0004 היה עושה \u0003לכל קרן וקרן.\u0004 משמע שהמזבח היה מרובע מכל צד, וכדברי לוי!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006"],["\u0003דגייז ליה\u0004 \u0005[שחותך אותו],\u0006 שאחר היציקה היה שובר אותו חלק מן היסוד — הלא \u0003\"אבנים שלמות\u0004 תבנה את מזבח ה' אלקיך\" (דברים כז, ו) \u0003כתיב\u0004 \u0005[נאמר]!\u0006","ומשיבים: היציקה מתחילה לא כללה את החלק הזה של היסוד, \u0003דמחית מידי מתותיה\u0004 \u0005[ש\u0006היה \u0005מניח\u0006 מתחילה \u0005משהו מתחתיו,\u0006 במקומו של אותו חלק\u0005],\u0006 \u0003ו\u0004אחר שנתייבשה \u0005היציקה\u0006 \u0003שקיל ליה\u0004 \u0005[היה נוטל אותו].\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך],\u0006 שהיו יוצקים בדרך זו, \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב כהנא: אבנים של קרנות\u0004 שבארבע פינות המזבח \u0003חלולות היו,\u0004 וראיה לדבר, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ומלאו כמזרק כזוית מזבח\"\u0004 (זכריה ט, טו), משמע שהקרנות היו חלולות וניתן היה למלא אותן כמזרקי יין — \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 הרי \u0003\"אבנים שלמות\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 לגבי אבני המזבח, וכיצד ניתן היה לעשות בהן חלל ונקבים? \u0003אלא דמחית מידי מתותיה ושקיל ליה\u0004 \u0005[שמניח משהו מתחתיו,\u0006 במקומו, \u0005ו\u0006אחר כך \u0005נוטל אותו]\u0006 כך שיוצאת הקרן חלולה, \u0003הכא נמי דמחית מידי מתותיה ושקיל ליה\u0004 \u0005[כאן גם כן,\u0006 בענין היסוד, מדובר \u0005שמניח משהו מתחתיו ו\u0006אחר כך \u0005נוטל אותו].\u0006","כיון שדובר במקום המזבח והמקדש, מביאים מה ש\u0003דרש רבא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"וילך דוד ושמואל וישבו בנית ברמה\"\u0004 (ראה שמואל א יט, יח— יט)? \u0003וכי מה ענין נויות אצל רמה?\u0004 הרי שני מקומות הם! \u0003אלא, שהיו יושבין ברמה ועוסקין בנויו של עולם,\u0004 כלומר, במקדש, שהוא עיקר יופיו של העולם.","וכשעסקו בשאלה היכן ייבנה, היו \u0003אמרי\u0004 \u0005[אומרים],\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"וקמת ועלית אל המקום\"\u0004 (דברים יז, ח), \u0003מלמד שבית המקדש גבוה מכל ארץ ישראל, וארץ ישראל גבוהה מכל ארצות. לא הוו ידעי דוכתיה היכא\u0004 \u0005[ידעו מקומו היכן\u0006 הוא\u0005],\u0006 איפה הוא המקום הגבוה,","\u0003אייתו\u0004 \u0005[הביאו]\u0006 את \u0003ספר יהושע\u0004 ובדקו בתיאור נחלת שבט יהודה, ומצאו כי \u0003בכולהו כתיב\u0004 \u0005[בכולם,\u0006 בכל הגבולות של נחלת יהודה \u0005נאמר]:\u0006 \u0003\"וירד\u0004 הגבול\" \u0003\"ועלה הגבול\" \"ותאר הגבול\"\u0004 (יהושע ט״ו:ט׳), ואילו \u0003ב\u0004גבולו עם \u0003שבט בנימין \"ועלה\" כתיב\u0004 \u0005[נאמר],\u0006 \u0003\"וירד\" לא כתיב\u0004 \u0005[נאמר],\u0006 \u0003אמרי\u0004 \u0005[אומרים\u0006 היו\u0005]:\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003הכא\u0004 \u0005[כאן]\u0006 \u0003הוא מקומו.\u0004","\u0003סבור למבנייה\u0004 \u0005[סבורים\u0006 היו \u0005לבנות אותו]\u0006 \u0003בעין עיטם, דמדלי\u0004 \u0005[ש\u0006הוא המקום \u0005הגבוה\u0006 יותר\u0005]\u0006 בגבול בנימין, \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003ניתתי ביה קליל\u0004 \u0005[נוריד אותו מעט],\u0006 \u0003כדכתיב\u0004 \u0005[כמו שנאמר]:\u0006 \u0003\"ובין כתפיו שכן\"\u0004 (דברים לג, יב), לומר שהוא מצוי כמו בין הכתפים ולא על הראש.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 כך אמרו: \u0003גמירי\u0004 \u0005[למודים אנו\u0006 במסורת\u0005],\u0006 ש\u0003סנהדרין\u0004 יושבת \u0003בחלקו\u0004 של \u0003יהודה, ושכינה בחלקו\u0004 של \u0003בנימין,\u0004 וכן למודים היו במסורת כי מקומה של הסנהדרין במקדש, \u0003ואי מדלינן ליה\u0004 \u0005[ואם אנו מגביהים אותו]\u0006 כלומר, בונים אותו במקום הגבוה יותר, עין עיטם — \u0003מתפליג טובא\u0004 \u0005[מתרחק הרבה]\u0006 מקום המקדש מנחלת יהודה ואינו נכנס בתחומה, \u0003מוטב דניתתי ביה פורתא\u0004 \u0005[שנוריד בו מעט],\u0006 \u0003כדכתיב\u0004 \u0005[כמו שנאמר]:\u0006 \u0003\"ובין כתפיו שכן\".\u0004","\u0003ועל דבר זה,\u0004 שישב דוד עם שמואל, ומצאו את המקום הראוי למקדש, \u0003נתקנא דואג האדומי בדוד, כדכתיב\u0004 \u0005[כמו שנאמר]:\u0006 \u0003\"כי קנאת ביתך אכלתני\u0004 וחרפות חורפיך נפלו עלי\" (תהלים סט, י). \u0003ו\u0004בענין זה של מציאת המקום המתאים \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"זכור ה' לדוד את כל ענותו אשר נשבע לה' וגו' אם אבא באהל ביתי אם אתן שנת לעיני לעפעפי תנומה עד אמצא מקום לה' וגו'.\u0004","\u0003הנה שמענוה באפרתה מצאנוה בשדה יער\"\u0004 (תהלים קלב, ו), \"שמענוה \u0003באפרתה\"\u0004 — \u0003זה\u0004 ספרו של \u0003יהושע דקאתי\u0004 \u0005[שבא]\u0006 \u0003מאפרים,\u0004 ששמעו והבינו את המקום הראוי מתוך עיון בספר יהושע, \u0003\"מצאנוה בשדה יער\"\u0004 — \u0003זה בנימין\u0004 שמצאו את המקום בנחלתו, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בנימין זאב יטרף\"\u0004 (בראשית מט, כז), שהוא מחיות היער.","\u0003זבחי שלמי צבור ואשמות; אלו הן אשמות,\u0004 שיש בהם כמה סוגים: \u0003אשם גזילות\u0004 שמביא אדם שחבירו תובעו ממון, והוא מכחש בו ונשבע על כך לשקר (ויקרא ה, כ— כו), \u0003אשם מעילות\u0004 שמביא מי שנהנה מן הקדש בשגגה (ויקרא ה, יד— טז), \u0003אשם שפחה חרופה\u0004 שמביא מי שבא על שפחה כנענית המאורסת לעבד עברי (ויקרא יט, כ— כב), \u0003אשם נזיר\u0004 שמביא לטהרתו (במדבר ו, יב), \u0003אשם מצורע\u0004 שמביא לטהרתו (ויקרא יד, יב), ו\u0003אשם תלוי\u0004 אם עשה מעשה ולא ברור לו אם הוא חייב עליו חטאת או לא (ויקרא ה, יז— יח) — כל אלה","\u0003שחיטתן בצפון, וקיבול דמן בכלי שרת בצפון, ודמן טעון שתי מתנות שהן ארבע, ונאכלין לפנים מן הקלעים\u0004 כלומר, בתוך העזרה, \u0003לזכרי כהונה\u0004 לזכרים בין הכהנים, \u0003לכל מאכל\u0004 צלי או מבושל, ונאכלים \u0003ליום ולילה עד חצות\u0004 הלילה."],["ומבררים: שלמי ציבור, דהיינו שני כבשי שלמים, הבאים בעצרת עם שני הלחם, \u0003מנא לן דבעי\u0004 \u0005[מנין לנו שצריכים]\u0006 שחיטה ב\u0003צפון? דתני\u0004 \u0005[ששנה]\u0006 \u0003רבה בר רב חנן קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא,\u0004 נאמר בענין זה: \u0003\"ועשיתם שעיר עזים אחד לחטאת\u0004 ושני כבשים בני שנה לזבח שלמים\" (ויקרא כג, יט), ומקישים את שני הכבשים לחטאת: \u0003מה חטאת\u0004 נשחטת \u0003בצפון, אף שלמי צבור בצפון.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: וכי חטאת מהיכן למדה\u0004 שהיא בצפון? \u0003מעולה,\u0004 והרי נלמד הדבר בהיקש (\"במקום אשר תשחט העולה תשחט החטאת\". ויקרא ו, יח), וכי \u0003דבר הלמד בהיקש חוזר ומלמד בהיקש\u0004 בדיני קדשים?","\u0003אלא\u0004 יש לומר שהמקור הוא \u0003מדתני\u0004 \u0005[ממה ששנה]\u0006 \u0003רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא,\u0004 שנאמר: \"וביום שמחתכם ובמועדיכם ובראשי חדשיכם ותקעתם בחצוצרות \u0003על עלתיכם ועל זבחי שלמיכם\"\u0004 (במדבר י, י), ובכתוב זה הוקשו זבחי שלמי ציבור במישרין לעולה: \u0003מה עולה קדשי קדשים\u0004 — \u0003אף זבחי שלמי צבור קדשי קדשים, מה עולה בצפון אף זבחי שלמי צבור בצפון.\u0004","ושואלים: \u0003אלא היקשא קמא למאי אתא\u0004 \u0005[ההיקש הראשון,\u0006 לשעיר חטאת, \u0005למה בא]?\u0006 ומשיבים: לומר שדינם \u0003כי\u0004 \u0005[כמו]\u0006 \u0003חטאת, מה חטאת אינה נאכלת אלא לזכרי כהונה, אף זבחי שלמי צבור\u0004 אינם נאכלים אלא \u0003לזכרי כהונה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי הכי\u0004 \u0005[אם כך],\u0006 לפי שיטת לימוד זו, \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003איל נזיר, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והקריב את קרבנו לה' כבש בן שנתו\u0004 \u0003תמים אחד לעלה וכבשה אחת בת שנתה [תמימה] לחטאת\u0004 \u0003ואיל אחד [תמים] לשלמים\"\u0004 (במדבר ו, יד), \u0003הכי נמי נימא\u0004 \u0005[כך גם כן נאמר]\u0006 ש\u0003הקיש הכתוב\u0004 את השלמים של הנזיר \u0003לחטאת,\u0004 ונאמר: \u0003מה חטאת אינה נאכלת אלא לזכרי כהונה, אף איל נזיר\u0004 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אינו נאכל אלא לזכרי כהונה?\u0004 והרי במשנה להלן נאמר כי הוא נאכל לכל אדם!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משוה]?!\u0006 \u0003התם\u0004 \u0005[שם],\u0006 באיל נזיר, \u0003כיון דכתיב\u0004 \u0005[שנאמר]\u0006 אחר כך: \u0003\"ולקח הכהן את הזרע בשלה מן האיל\"\u0004 (במדבר ו, יט), ובהמשך נאמר שהוא לכהן, \u0003מכלל\u0004 הדברים אתה למד \u0003דכוליה\u0004 \u0005[ש\u0006את האיל \u0005כולו]\u0006 \u0003בעלים אכלי ליה\u0004 \u0005[אוכלים אותו].\u0006","ומקשים: \u0003זרוע בשלה מיהא\u0004 \u0005[על כל פנים]\u0006 ש\u0003לא ליתאכיל\u0004 \u0005[תיאכל]\u0006 לשיטתך \u0003אלא לזכרי כהונה,\u0004 שהרי אינה נאכלת לבעלים, ובמשנה להלן נאמר כי היא נאכלת לכהנים, לנשיהם ולעבדיהם! ואומרים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר, שכך היה צריך ללמוד מן ההיקש.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ לשאלה זו: \u0003קדשי אקרי\u0004 \u0005[קדשים נקרא]\u0006 אותה זרוע של איל הנזיר (\"קודש הוא לכהן\". במדבר ו, כ), אבל \u0003קדשי קדשים לא\u0004 \u0003איקרו\u0004 \u0005[נקראו].\u0006 \u0003ו\u0004שואלים: אם כן, \u0003אלא למאי הלכתא איתקש\u0004 \u0005[לאיזו הלכה הוקש]\u0006 איל השלמים לקרבנות האחרים? \u0003אמר רבא:\u0004 ללמד את מה שנאמר בשלמים גם לגבי העולה והחטאת, \u0003שאם גלח\u0004 את שערו \u0003על אחד משלשתן\u0004 כלומר, גם אם לא הקריב אלא רק קרבן אחד מהם — \u0003יצא\u0004 ידי חובתו.","\u0003התודה\u0004 (ראה ויקרא ז, יב) \u0003ואיל נזיר\u0004 (במדבר ו, יד) \u0003קדשים קלים\u0004 הם, שאין בהם דין מעילה, \u0003שחיטתן בכל מקום בעזרה\u0004 (ולא רק בצפון), \u0003ודמן טעון שתי מתנות שהן ארבע, ונאכלין בכל העיר\u0004 ירושלים, \u0003לכל אדם\u0004 בין שהוא כהן בין שהוא ישראל, \u0003בכל מאכל,\u0004 ונאכלים \u0003ליום ולילה עד חצות\u0004 הלילה. \u0003המורם מהם\u0004 אותו חלק שמרימים מהם ונותנים לכהנים דינו \u0003כיוצא בהן\u0004 לגבי זמן האכילה ומקומה (בכל העיר, ליום ולילה), \u0003אלא שהמורם נאכל\u0004 רק \u0003לכהנים, לנשיהם ולבניהם ולעבדיהם.\u0004","בענין המורם לכהנים מקדשים קלים, שהוא נאכל בכל העיר, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר לכהנים \u0003\"את חזה התנופה ואת שוק התרומה\u0004 (מן השלמים) \u0003תאכלו במקום טהור\"\u0004 (ויקרא י, יד), \u0003אמר ר' נחמיה:\u0004 מה צורך לומר זאת? \u0003וכי\u0004 קרבנות \u0003ראשונים\u0004 שהוזכרו בפסוק הקודם \u0003בטומאה אכלום?\u0004 והרי מדובר שם על שיירי המנחה, הנאכלים בעזרה!","\u0003אלא\u0004 כשהוא אומר \u0003טהור\u0004 — \u0003מכלל שהוא טמא\u0004 כלומר, שהוא טהור רק באופן מוגבל, ועניינו: שהוא מקום \u0003טהור מטומאת מצורע\u0004 (שמצורע אסור להיכנס לתוכו) אבל \u0003טמא מטומאת זב, ואיזה זה\u0004 המקום? \u0003זה מחנה ישראל\u0004 במדבר, וכשנבנה בית המקדש — בכל ירושלים, וכדין משנתנו.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: את חזה התנופה וכו' תאכלו במקום \u0003טהור מטומאת זב וטמא מטומאת מת, ואיזה זה? זה מחנה לויה,\u0004 ובירושלים — רק בהר הבית!","\u0003אמר אביי, אמר קרא\u0004 \u0005[המקרא]\u0006 בפסוק הקודם, לענין מנחה: \u0003\"ואכלתם אתה במקום קדוש\"\u0004 (ויקרא י, יג), ויש בכך הדגשה: \u0003אותה\u0004 אוכלים \u0003במקום קדוש\u0004 בעזרה, שהיא מחנה שכינה, \u0003ולא אחרת במקום קדוש,\u0004 והם חזה התנופה ושוק התרומה האמורים שם, ובכך \u0003אפקה\u0004 \u0005[הוציא אותה]\u0006 איפוא \u0003למחנה לויה,\u0004 שאין צורך לאכול אותם דווקא בעזרה, אלא בכל הר הבית, \u0003הדר כתיב\u0004 \u0005[חזר וכתב]\u0006 לגביהם: \"את חזה התנופה וכו' תאכלו \u0003במקום טהור\",\u0004 ובהדגשה זו \u0003אפקה\u0004 \u0005[הוציא אותה]\u0006 \u0003למחנה ישראל.\u0004","\u0003רבא אמר\u0004 באופן אחר: הדיוק \u0003\"אתה במקום קדוש\" ולא אחרת במקום קדוש, אפקה\u0004 \u0005[הוציא אותה]\u0006 את חזה התנופה וכו' \u0003לגמרי,\u0004 ולפי זה אפשר היה לאכול אותם בכל מקום, אפילו מחוץ למחנה ישראל (ובזמן המקדש — חוץ לירושלים), אבל \u0003הדר כתב רחמנא\u0004 \u0005[חזרה וכתבה התורה]:\u0006 \u0003\"תאכלו במקום טהור\",\u0004 ובכך \u0003עיילא\u0004 \u0005[הכניס אותה]\u0006 \u0003למחנה ישראל,\u0004 שיש בו טהרה לעומת מה שחוץ לו.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003עיילא\u0004 \u0005[הכניס אותה]\u0006 בכך \u0003למחנה לויה,\u0004 שהוא הקרוי \"מקום טהור\"! ומשיבים: \u0003לחדא מעיילינן, לתרתי לא מעיילינן\u0004 \u0005[ל\u0006מחיצה \u0005אחת מכניסים אנו, לשתים אין אנו מכניסים].\u0006","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 לפי כלל זה, \u0003אפוקי נמי\u0004 \u0005[להוציא גם כן],\u0006 נאמר \u0003:\u0004 \u0003לחדא מפקינן, מתרתי לא מפקינן\u0004 \u0005[מ\u0006מחנה \u0005אחד אנו מוציאים, משנים אין אנו מוציאים],\u0006 וכיצד דרשת מתחילה ש\"אותה במקום קדוש\" בא להתיר לאכול חזה ושוק מחוץ למחנה ישראל! \u0003ועוד\u0004 מקשים על רבא: איך ניתן היה מתחילה להעלות אפשרות לאכול קדשים בכל מקום? והלא \u0003\"לא תוכל לאכול בשעריך...\u0004 וכל נדריך אשר תדור ונדבותיך\" (דברים יב, יז) \u0003כתיב\u0004 \u0005[נאמר]!\u0006 \u0003אלא, מחוורתא\u0004 \u0005[מחוורים הדברים]\u0006 \u0003כ\u0004דברי \u0003אביי.\u0004","\u0003שלמים קדשים קלים\u0004 הם, ו\u0003שחיטתן בכל מקום בעזרה, ודמן טעון שתי מתנות שהן ארבע, ונאכלין בכל העיר, לכל אדם, בכל מאכל, לשני ימים ולילה אחד,\u0004 ובזה שונים הם מתודה ואיל נזיר. \u0003המורם מהם כיוצא בהם\u0004 לגבי מקום וזמן האכילה, \u0003אלא שהמורם נאכל לכהנים, לנשיהם ולבניהם ולעבדיהם.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר לגבי קרבן שלמים מן הבקר: \u0003\"ושחטו פתח אהל מועד\"\u0004 (ויקרא ג, ב), ובשלמים מן הכבשים נאמר: \u0003\"ושחט אתו לפני אהל מועד\"\u0004 (ויקרא ג, ח), ועוד נאמר במביא עז לשלמים: \u0003\"ושחט אותו לפני אהל מועד\"\u0004 (ויקרא ג, יג).","וכתוב זה שאין בו תוספת על האמור קודם לכן — הרי זה בא \u0003להכשיר את כל הרוחות\u0004 (הצדדים) את כל העזרה \u0003בקדשים קלים\u0004 שכל מקום בעזרה שהוא לפני אוהל מועד — כשר לכך. ומכאן \u0003קל וחומר לצפון\u0004 שכשר לכך, ומהו קל וחומר זה? \u0003ומה קדשי קדשים שלא הוכשרו בכל הרוחות\u0004 (הצדדים) \u0003הוכשרו בצפון,\u0004 שנאמר בעולה \"על ירך המזבח צפונה\" (ויקרא א, יא), ומשם למדנו לשאר קדשי קדשים, \u0003קדשים קלים שהוכשרו בכל הרוחות\u0004 — \u0003אינו דין שהוכשרו בצפון?\u0004","\u0003ר' אליעזר אומר: לא נאמר הכתוב\u0004 הנוסף \u0003אלא להכשיר צפון\u0004 לשחיטת קדשים קלים, \u0003שיכול\u0004 כלומר, אפשר היה לומר מן הסברה שאינו כך, \u0003והלא דין\u0004 (סברה) \u0003הוא:\u0004 \u0003ומה קדשים קלים\u0004 \u0003שהוכשרו בכל הרוחות\u0004 — \u0003לא הוכשר מקומן אצל קדשי קדשים,\u0004 שאין רשאים לשחוט קדשי קדשים בכל רוח, \u0003קדשי קדשים שלא הוכשרו אלא בצפון\u0004 — \u0003אינו דין שלא הוכשר מקומן אצל קדשים קלים?\u0004 \u0003תלמוד לומר:\u0004 \"לפני \u0003אהל מועד\",\u0004 ללמד שקדשים קלים נשחטים אף בצפון."],["ומסבירים: \u0003במאי קא מיפלגי\u0004 \u0005[במה חלוקים הם]?\u0006 ה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 כך: \u0003תלתא קראי כתיבי\u0004 \u0005[שלושה מקראות כתובים],\u0006 \u0003חד\u0004 \u0005[אחד]\u0006 שנאמר בו \"ושחטו פתח אוהל מועד\" (ויקרא ג, ב) — \u0003לגופיה דניבעי\u0004 \u0005[לגופו, להצריך]\u0006 שתהא השחיטה \u0003פתח אהל מועד,\u0004 כאשר יבואר להלן, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 שנאמרה בו הלשון \"לפני אוהל מועד\" (\u0003ויקרא ג, ח\u0004) — \u0003להכשיר צדדין\u0004 כלומר, כל רוחב העזרה שמול פני אוהל מועד, ולא רק מה שהוא בדיוק מול פתח אוהל מועד, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 שנאמר בו שוב \"לפני אוהל מועד\" (ויקרא ג, יג) — \u0003לפסול צידי צדדין,\u0004 מקום שהוא בצידי העזרה ואינו כנגד פני אוהל מועד כלל. \u0003ו\u0004לגבי שחיטה ב\u0003צפון לא איצטריך קרא\u0004 \u0005[הוצרך פסוק]\u0006 להכשיר לדעת התנא קמא, שהרי לדבריו נלמד הדבר בקל וחומר.","\u0003ור' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003חד לגופיה דניבעי\u0004 \u0005[\u0006פסוק \u0005אחד לגופו שצריכים]\u0006 \u0003פתח אהל מועד, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003להכשיר צפון, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003להכשיר צדדין, ו\u0004לדעתו \u0003צידי צדדין לא איצטריך קרא\u0004 \u0005[הוצרך פסוק]\u0006 למעט אותם.","ועל ההבדל שבין המקראות האמורים בשחיטת השלמים שואלים: \u0003מאי שנא הכא דכתיב\u0004 \u0005[במה שונה כאן,\u0006 בפר, \u0005שנאמר]\u0006 \u0003\"פתח אהל מועד\"\u0004 (ויקרא ג, ב) \u0003ומאי שנא התם דכתיב\u0004 \u0005[ומה שונה שם,\u0006 בצאן, \u0005שנאמר]\u0006 \u0003\"לפני אהל מועד\"\u0004 (ויקרא ג, ח) מדוע הוזכר הפתח באחד מהם? ומשיבים: \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 בכך \u0003כ\u0004מו שאמר \u0003רב יהודה אמר שמואל,\u0004 ש\u0003אמר רב יהודה אמר שמואל: שלמים ששחטן\u0004 בעזרה \u0003קודם שיפתחו דלתות ההיכל\u0004 — \u0003פסולין, שנאמר: \"ושחטו פתח אהל מועד\"\u0004 (ויקרא ג, ב), לומר: \u0003בזמן שהוא פתוח ולא בזמן שהוא נעול.\u0004","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 בשם אמוראים אחרים וכיוצא בזה: \u0003אמר מר עוקבא בר חמא אמר ר' יוסי בר' חנינא: שלמים ששחטן קודם שיפתחו דלתות ההיכל\u0004 — \u0003פסולין, שנאמר: \"ושחטו פתח אהל מועד\"\u0004 (ויקרא ג, ב), \u0003בזמן שפתח ההיכל פתוח ולא בזמן שהוא נעול.\u0004","\u0003במערבא מתני הכי\u0004 \u0005[במערב,\u0006 בארץ ישראל \u0005היו שונים כך],\u0006 \u0003אמר רב יעקב בר אחא אמר רב אשי: שלמים ששחטן קודם שיפתחו דלתות ההיכל\u0004 — \u0003פסולים. ובמשכן,\u0004 שלא היו בו דלתות, אם שחטם \u0003קודם שיעמידו לוים את המשכן, ו\u0004כן \u0003לאחר שיפרקו לוים את המשכן\u0004 — \u0003פסולים.\u0004","ומבררים פרטי ענין זה, ואומרים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005],\u0006 שאם הפתח \u0003מוגף\u0004 (סגור, אף שאינו נעול) \u0003כנעול דמי\u0004 \u0005[נחשב הוא],\u0006 והשאלה היא: \u0003וילון\u0004 פרוס על הפתח \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 \u0003אמר ר' זירא: הוא עצמו,\u0004 וילון, \u0003אין נעשה אלא\u0004 השתמש בו \u0003כ\u0004אשר ה\u0003פתח פתוח.\u0004","ועוד שואלים: \u0003גובהה מאי\u0004 \u0005[\u0006אם היה דבר \u0005גבוה\u0006 מול הפתח \u0005מה\u0006 דינו\u0005]?\u0006 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי בר' יהודה אומר: שני פשפשין\u0004 (פתחים קטנים) \u0003היו ב\u0004כתלים המערביים של \u0003בית החליפות\u0004 (האגפים הצדדיים של האולם המצוי בפתחו של ההיכל), \u0003וגובהן שמנה\u0004 אמות, \u0003כדי להכשיר את העזרה כולה לאכילת קדשי קדשים ולשחיטת קדשים קלים,\u0004 שכך נמצא חלקה המערבי (האחורי) של העזרה קרוי \"לפני אוהל מועד\".","\u0003מאי לאו דאיכא קמייהו\u0004 \u0005[האם אין\u0006 הכוונה \u0005שיש לפניהם]\u0006 גובה \u0003שמונה\u0004 אמות? ומשיבים: \u0003לא,\u0004 הכוונה היא \u0003דגבהו נינהו\u0004 \u0005[שגובהם שלהם\u0006 עצמם \u0005הוא]\u0006 \u0003שמונה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003כל השערים שהיו שם\u0004 במקדש, \u0003גובהן עשרים אמה ורוחבן עשר אמה,\u0004 ואם כן איך אפשר לומר שגובהם שמונה? ומשיבים: \u0003פשפשין שאני\u0004 \u0005[שונים],\u0006 שאינם בכלל השערים, אלא הם דלתות קטנות מיוחדות. ולגופה של הברייתא מקשים: כיצד אותם פשפשים מכשירים את העזרה כולה?","\u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003צדדין\u0004 מצפון ומדרום לבית החליפות, שאינם פונים אל הפשפשים שבמערב? ומשיבים: \u0003דמעייל להו\u0004 \u0005[שמכניס אותם]\u0006 כלומר, פותח את הפשפשים \u0003בקרן זוית,\u0004 כך שהם פונים לכל צד.","ועוד שואלים: \u0003אחורי בית הכפורת\u0004 כלומר, השטח שמאחורי כותלו המערבי של ההיכל \u0003מאי\u0004 \u0005[מהו]?\u0006 הרי אין הוא רואה את הפשפשים! ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה ממה ש\u0003אמר רמי בר רב יהודה אמר רב: לול\u0004 (פתח, חלון) \u0003קטן היה אחורי בית הכפורת גבוה שמונה אמות, כדי להכשיר את העזרה לאכילת קדשי קדשים ולשחיטת קדשים קלים. והיינו דכתיב\u0004 \u0005[והוא שנאמר]\u0006 ברשימת השומרים על שערי המקדש: \u0003\"שנים לפר בר\"\u0004 (דברי הימים א כו, יח). ושואלים: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003\"לפר בר\"? אמר רבה בר רב שילא: כמאן דאמר\u0004 \u0005[כמי שאומר]\u0006 \u0003כלפי בר\u0004 \u0005[חוץ],\u0006 שפתח זה היה מופנה לצד חוץ, מן הקודש כלפי מערב.","\u0003אמר ר' יהודה אמר שמואל: אין חייבין משום טומאה\u0004 שבמקדש \u0003אלא על\u0004"],["\u0003אורך מאה ושמונים ושבע על רוחב מאה ושלשים וחמש\u0004 אמות, שהוא תחום העזרה.","מסופר, \u0003תני\u0004 \u0005[שונה]\u0006 היה ה\u0003תנא,\u0004 חוזר המשניות \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן\u0004 את המשנה במסכת מדות: \u0003כל העזרה היתה מאה שמונים ושבע על רוחב מאה\u0004 \u0003שלשים וחמש. אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן, \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר לי אבא: כגון\u0004 \u0003זה\u0004 כלומר, בכל השטח הזה, \u0003כהנים נכנסין לשם ואוכלין שם קדשי קדשים,\u0004 \u0003ושוחטין שם קדשים קלים, וחייבין\u0004 כרת הנכנסים לשם כשהם טמאים \u0003משום טומאה.\u0004","ושואלים: \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 באה הדגשה זאת? \u0003אילימא למעוטי\u0004 \u0005[אם תאמר למעט]\u0006 \u0003חלונות דלתות ועובי החומה,\u0004 שאין דינם כדין העזרה, אלא כדין הר הבית — הלוא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 להיפך: \u0003החלונות ועובי החומה\u0004 דינם \u0003כלפנים!\u0004","\u0003ואלא\u0004 באה \u0003למעוטי\u0004 \u0005[למעט]\u0006 את ה\u0003לשכות\u0004 שבעזרה. ויש לברר: \u0003ו\u0004באיזה לשכות מדובר, \u0003אי\u0004 \u0005[אם]\u0006 הן \u0003בנויות בחול\u0004 מחוץ לתחום הזה, \u0003ופתוחות לקדש, והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003תוכן\u0004 של הלשכות הללו הפתוחות לקודש גם הוא \u0003קודש!\u0004 ומשיבים: \u0003מדרבנן\u0004 \u0005[מ\u0006דברי \u0005חכמים]\u0006 הוא, שיש להן דין עזרה, אבל מדין תורה אין תוכן קודש.","ותוהים: \u0003ודאורייתא לא\u0004 \u0005[ומן התורה אינן\u0006 קודש]? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003לשכות\u0004 שהיו \u0003בנויות בחול ופתוחות לקדש, מנין שהכהנים נכנסין לשם ואוכלים שם קדשי קדשים ושירי מנחה? תלמוד לומר\u0004 לגבי המנחה הנאכלת בעזרה: \"תאכל במקום קדוש \u0003בחצר אהל מועד יאכלוה\"\u0004 (ויקרא ו, ט), ודי היה לומר \"במקום קדוש\" שהוא העזרה, ובמה שנאמר \"בחצר אוהל מועד\" \u0003התורה ריבתה חצירות הרבה אצל אכילה אחת.\u0004 ואם לשכות אלה אינן קדושות ממש — לא היו חכמים מתירים איסור תורה לאכול קדשי קדשים בחול!","\u0003אמר רבא: לאכילה שאני\u0004 \u0005[שונה]\u0006 הדבר, שיש בזה ריבוי מיוחד, שלא רק בעזרה עצמה ניתן לאכול קדשי קדשים, אלא גם במה שפתוח אליה. אבל אין הדין כן לענין שחיטת קדשים קלים, וחיוב כרת על טומאה.","ומקשים: \u0003אבל לענין טומאה לא\u0004 אין חייבים שם? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003לשכות הבנויות לחול ופתוחות לקודש, כהנים נכנסין לשם\u0004 \u0003ואוכלין שם קדשי קדשים, ואין שוחטין שם קדשים קלים,\u0004 \u0003וחייבין\u0004 עליהם \u0003משום טומאה!\u0004","ומשיבים: \u0003לאו אמרת\u0004 \u0005[האם לא אמרת]\u0006 ש\u0003אין שוחטין\u0004 שם? \u0003תני נמי\u0004 \u0005[שנה גם כן]\u0006 ותקן: \u0003אין חייבין\u0004 גם משום טומאה.","ומקשים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שאתה אומר \u0003אין שוחטין\u0004 — יש טעם לדבר, כי \u0003בעינא\u0004 \u0005[צריכים אנו]\u0006 שתהיה השחיטה \u0003כנגד הפתח,\u0004 כפי שלמדנו בעמוד הקודם (נה,ב), שנאמר: \"ושחטו פתח אהל מועד\" (ויקרא ג, ב) \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי הוא שוחט בתוך הלשכה. \u0003אלא אין חייבין\u0004 משום טומאה, \u0003אמאי\u0004 \u0005[מדוע]?\u0006","ומשיבים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 מה ששנינו \u0003אין שוחטין, מי לא עסקינן דאיכא\u0004 \u0005[האם אין אנו עוסקים\u0006 גם במקרה \u0005שיש]\u0006 \u0003שחיטה כנגד הפתח? דאי ליכא\u0004 \u0005[שאם אין]\u0006 מדובר גם בשחיטה כנגד הפתח, \u0003למאי איצטריך\u0004 \u0005[למה הוצרך]\u0006 לשנות דין זה בלשכות? הרי ממילא אי אפשר לשחוט שם מהטעם שאין זה כנגד הפתח! \u0003אלא אף על גב דקא שחיט\u0004 \u0005[אף על פי שהוא שוחט]\u0006 \u0003כנגד הפתח,\u0004 \u0003תני\u0004 \u0005[\u0006הריהו \u0005שונה]\u0006 \u0003אין שוחטין, משום\u0004 שלדעת התנא \u0003לא קדיש\u0004 \u0005[קדוש\u0006 המקום\u0005]\u0006 בקדושת העזרה. אם כן, מסיבה זו עצמה \u0003תני נמי\u0004 \u0005[שנה גם כן]:\u0006 \u0003אין חייבין\u0004 שם משום טומאה. ומכל מקום לענין אכילה ריבה הכתוב אותן לשכות, ואוכלים בהן קדשי קדשים.","ושואלים: \u0003ו\u0004האם \u0003לאכילה לא בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה המקום \u0003כנגד הפתח? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי בר' יהודה\u0004 \u0003אומר: שני פשפשין\u0004 (פתחים קטנים) \u0003היו בבית החליפות\u0004 בצד המערבי הפונה לאחורי העזרה, שהיה \u0003גובהן שמונה\u0004 אמות, \u0003כדי להכשיר את העזרה\u0004 כולה \u0003לאכילת קדשי קדשים ולשחיטת קדשים קלים.\u0004 משמע שאף לאכילה צריך שיהא המקום כנגד הפתח! \u0003אמר רבינא: סמי\u0004 \u0005[מחק]\u0006 \u0003מכאן אכילה,\u0004 שלענין אכילה לא צריך כנגד פתח.","ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 לאהרן ולבניו בימי חנוכת המשכן: \u0003\"בשלו את הבשר פתח אהל מועד ושם\u0004 \u0003תאכלו אותו\"\u0004 (ויקרא ח, לא), משמע שאף האכילה צריכה להיות בפתח אוהל מועד! ודוחים: \u0003קדשי שעה שאני\u0004 \u0005[שונים],\u0006 ושם גזירת הכתוב היא שיאכלו בפתח אהל מועד, אבל אין הדין כן בקדשים לדורות.","\u0003אמר רב יצחק בר אבודימי: מנין לדם שנפסל בשקיעת החמה\u0004 ושוב אינו ראוי לזריקה על המזבח? \u0003שנאמר: \"ביום הקריבו את זבחו יאכל\"\u0004 (ויקרא ז, טז), ומכאן אנו למדים: \u0003ביום שאתה זובח\u0004 (שוחט) בו — \u0003אתה מקריב\u0004 וזורק את הדם, \u0003ביום שאי אתה זובח\u0004 — \u0003אי אתה מקריב.\u0004","ואומרים: \u0003האי מיבעי ליה\u0004 \u0005[\u0006פסוק \u0005זה נצרך לו]\u0006"],["\u0003לגופיה\u0004 \u0005[לגופו],\u0006 שנאמר: \"ביום הקריבו את זבחו יאכל וממחרת\", לומר שזמן אכילת שלמים הוא לשני ימים! ודוחים: \u0003אם כן, נימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 רק: \u0003\"ביום זבחו יאכל\u0004 וממחרת\", \"ביום \u0003הקריבו\u0004 את זבחו\" \u0003למה לי?\u0004 מדוע נתלה הדבר ביום ההקרבה? \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003ביום שאתה זובח\u0004 (שוחט) \u0003אתה מקריב\u0004 (זורק את הדם), \u0003ביום שאי\u0004 (אין) \u0003אתה זובח אי אתה מקריב.\u0004","ומקשים: אם כך, שיום ההקרבה הוא העיקר, \u0003ודילמא הכי קאמר רחמנא\u0004 \u0005[ושמא כך אמרה התורה]:\u0006 \u0003אי קריב\u0004 \u0005[אם קרב,\u0006 נזרק\u0005]\u0006 ה\u0003דם האידנא\u0004 \u0005[עכשיו]\u0006 כלומר, ביום השחיטה — \u0003ניתאכיל\u0004 \u0005[שייאכל]\u0006 ה\u0003בשר האידנא\u0004 \u0005[עכשיו]\u0006 היום \u0003ולמחר, אי קריב\u0004 \u0005[אם קרב]\u0006 ה\u0003דם למחר\u0004 ביום שלאחר השחיטה — \u0003ניתאכיל\u0004 \u0005[שייאכל]\u0006 ה\u0003בשר למחר\u0004 כלומר, ליום הזריקה, \u0003וליומא אוחרא\u0004 \u0005[וליום שאחריו]!\u0006 ומשיבים: \u0003אם כן, נימא קרא\u0004 \u0005[שיאמר הכתוב]:\u0006 \u0003\"ביום הקריבו יאכל\u0004 וממחרת\", \u0003\"זבחו\" למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהאכילה תלויה \u0005בשני הדברים גם יחד, ולכן\u0006 \u0003ביום שאתה זובח אתה מקריבו, ביום שאי אתה זובח,\u0004 כלומר, שכבר שקעה החמה — \u0003אי אתה מקריבו.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בבעיה הבאה: \u0003ה\u0004שוחט את השלמים ו\u0003מחשב\u0004 לאוכלם \u0003לאור\u0004 (בליל) היום ה\u0003שלישי,\u0004 ודינם להיאכל רק לשני ימים — \u0003חזקיה אמר: כשר\u0004 הוא, ואין בזה משום מחשבת חוץ לזמנו, \u0003ר' יוחנן אמר: פסול.\u0004 ומסבירים: \u0003חזקיה אמר כשר\u0004 — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003לא אינתיק\u0004 \u0005[ניתק]\u0006 \u0003לשריפה,\u0004 שאין לשורפו אלא בבוקר יום השלישי (ויקרא יט, ו). \u0003ר' יוחנן אמר פסול\u0004 — \u0003דהא אידחי ליה\u0004 \u0005[שהרי\u0006 משנגמר היום השני \u0005נדחה לו]\u0006 כבר \u0003מאכילה.\u0004","ועוד נחלקו במחלוקת דומה: \u0003האוכל\u0004 מן הבשר שנשאר \u0003לאור שלישי\u0004 — \u0003חזקיה אמר: פטור\u0004 מכרת על אכילת נותר, משום ש\u0003לא אינתיק\u0004 \u0005[ניתק\u0006 עדיין\u0005]\u0006 \u0003לשריפה. ר' יוחנן אמר: חייב, דהא אידחי ליה\u0004 \u0005[שהרי נדחה לו]\u0006 \u0003מאכילה.\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן: קדשים הנאכלין ליום אחד,\u0004 אם \u0003מחשבין בדמן\u0004 לזורקו \u0003משתשקע החמה, ו\u0004כן אם מחשבים \u0003בבשרן ובאימוריהן\u0004 לאכול את הבשר או להקטיר את האימורים \u0003משיעלה עמוד השחר\u0004 — הרי זה פיגול. ואילו \u0003קדשים הנאכלין לשני ימים ולילה אחת,\u0004 \u0003מחשבין בדמן\u0004 לזורקו \u0003משתשקע החמה, ובאימוריהן\u0004 — \u0003משיעלה עמוד השחר, ו\u0004אילו \u0003בבשרן\u0004 — \u0003משתשקע החמה של שני ימים\u0004 (של היום השני). ומביאים ברייתא נוספת בענין זה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יכול יהו\u0004 שלמים \u0003נאכלין\u0004 גם \u0003לאור שלישי?\u0004 \u0003ו\u0004לכאורה \u0003דין הוא\u0004 שיהא כך: יש \u0003זבחים נאכלין ליום אחד\u0004 (כגון תודה) \u0003ו\u0004יש \u0003זבחים\u0004 ש\u0003נאכלין לשני ימים\u0004 (שלמים), \u0003מה זבחים הנאכלין ליום אחד\u0004 יש \u0003לילה אחריהן,\u0004 שאף הלילה כשר לאכול בזבחים אלה, \u0003אף זבחים הנאכלין לשני ימים\u0004 יהיה \u0003לילה אחריהן!\u0004","\u0003תלמוד לומר:\u0004 \"ביום זבחכם יאכל וממחרת \u0003והנותר עד יום\u0004 השלישי באש ישרף\" (ויקרא יט, ו) — \u0003בעוד יום הוא נאכל, ואינו נאכל לאור שלישי.\u0004","\u0003יכול ישרף מיד\u0004 לאחר שקיעת החמה? \u0003ודין הוא:\u0004 יש \u0003זבחים נאכלין ליום אחד ו\u0004יש \u0003זבחים נאכלין לשני ימים, מה זבחים הנאכלין ליום אחד, תיכף ל\u0004גמר זמן \u0003אכילה\u0004 — \u0003שריפה, אף זבחים הנאכלין לשני ימים תיכף לאכילה שריפה!\u0004","\u0003תלמוד לומר:\u0004 \"והנותר מבשר הזבח \u0003ביום השלישי באש ישרף\"\u0004 (ויקרא ז, יז) — \u0003ביום אתה שורפו, ואי\u0004 (אין) \u0003אתה שורפו בלילה.\u0004","\u0003הבכור והמעשר והפסח קדשים קלים\u0004 הם, \u0003שחיטתן בכל מקום בעזרה, ודמן טעון\u0004 רק \u0003מתנה אחת\u0004 על המזבח, \u0003ובלבד שיתן כנגד היסוד,\u0004 כלומר, שיזה את המתנה במקום שיש בו יסוד למזבח.","ואף שלענין עבודתם שווים הם, \u0003שינה באכילתן,\u0004 כלומר, בכל אחד מהקרבנות האלה יש דרך אחרת של אכילה, כיצד? \u0003הבכור נאכל לכהנים, והמעשר\u0004 נאכל \u0003לכל אדם, ו\u0004שניהם \u0003נאכלין בכל העיר\u0004 ירושלים, \u0003בכל מאכל, לשני ימים ולילה אחד.\u0004 ואילו \u0003הפסח אינו נאכל אלא בלילה, ואינו נאכל אלא עד חצות\u0004 הלילה, \u0003ואינו נאכל אלא למנויו\u0004 כלומר, לאלה שנמנו מראש שיאכלו ממנו, \u0003ואינו נאכל אלא צלי\u0004 ולא בכל מאכל, שאין אוכלים אותו מבושל או נא.","על מה ששנינו שדמם של הבכור והמעשר והפסח טעון זריקה על המזבח, שואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 שלשיטתו נאמרה משנה זו? \u0003אמר רב חסדא:\u0004 שיטת \u0003ר' יוסי הגלילי היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי הגלילי אומר:\u0004 בכתוב \"אך בכור שור או בכור כשב או בכור עז... את דמם תזרוק על המזבח ואת חלבם תקטיר\" (במדבר יח, יז), \u0003\"חלבו\" לא נאמר אלא \"חלבם\", \"דמו\" לא נאמר אלא \"דמם\", לימד על בכור ו\u0004גם על \u0003מעשר ופסח שטעונין מתן דמים ואימורין לגבי מזבח.\u0004","ועוד שואלים: וממה ששנינו שהדם הזה צריך להינתן \u0003כנגד היסוד מנא לן\u0004 \u0005[מנין לנו]?\u0006 \u0003אמר ר' אליעזר: אתיא\u0004 \u0005[באה,\u0006 נלמד\u0005]\u0006 בגזירה שווה מהמלים \u0003\"זריקה\" \"זריקה\" מעולה,\u0004 שכשם שהעולה נזרקת במקום שיש בו יסוד למזבח, כך הבכור והמעשר והפסח נזרק דמם במקום כזה."],["ושואלים: \u0003ועולה גופה מנלן\u0004 \u0005[מנין לנו]\u0006 שמתן דמה במקום שיש יסוד? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אל יסוד מזבח העולה\"\u0004 (ויקרא ד, כה), \u0003למד על עולת חובה שטעונה יסוד.\u0004","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 מעולה למדו בגזירה שווה, נאמר גם: \u0003מה להלן,\u0004 בעולה, זורקים \u0003שתי מתנות שהן ארבע, אף כאן,\u0004 בבכור מעשר ופסח, יצטרך לתת \u0003שתי מתנות שהן ארבע,\u0004 ולא רק מתנה אחת!","\u0003אמר אביי: למה לי למכתב\u0004 \u0005[לכתוב]\u0006 \u0003\"סביב\" בעולה\u0004 (ויקרא א, ה) וגם \u0003\"סביב\" בחטאת\u0004 (ויקרא ח, טו) ללמד שצריך ליתן על ארבעה צידי המזבח? והרי כבר נאמר בחטאת שצריך ליתן דמה על ארבע קרנות המזבח! אלא \u0003הוו\u0004 \u0005[הרי הם]\u0006 \u0003שני כתובין הבאין כאחד, וכל שני כתובין הבאין כאחד אין מלמדין.\u0004","ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 שני כתובים הבאים כאחד \u0003אין מלמדין, אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003מלמדין, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003הוי\u0004 \u0005[הרי]\u0006 \u0003אשם\u0004 שגם בו נאמר \"סביב\" (ויקרא ז, ב), ו\u0003שלשה\u0004 כתובים הבאים כאחד \u0003ודאי אין מלמדין.\u0004","שנינו במשנה: \u0003הבכור נאכל לכהנים,\u0004 ובשרו נאכל לשני ימים ולילה אחד. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין לבכור שנאכל לשני ימים ולילה? שנאמר\u0004 לאהרן ולבניו: \u0003\"ובשרם\u0004 (של הבכורות) \u0003יהיה לך כחזה התנופה וכשוק הימין\u0004 לך יהיה\" (במדבר יח, יח), \u0003הקישו הכתוב\u0004 את בשר הבכור \u0003לחזה ושוק של שלמים, מה שלמים נאכלין לשני ימים ולילה אחד, אף בכור נאכל לשני ימים ולילה אחד.\u0004","ומעירים: \u0003וזו שאלה נשאלה לפני חכמים בכרם ביבנה: בכור לכמה\u0004 ימים \u0003נאכל? נענה ר' טרפון ואמר: לשני ימים ולילה אחד.\u0004","\u0003היה שם תלמיד אחד שבא לבית המדרש לפני חכמים תחלה\u0004 כלומר, שישב בפעם הראשונה לפני החכמים ביבנה, \u0003ור' יוסי הגלילי שמו, אמר לו\u0004 לר' טרפון: \u0003רבי, מנין לך\u0004 שכך הוא? \u0003אמר לו: בני, שלמים קדשים קלים\u0004 הם \u0003ובכור\u0004 גם הוא \u0003קדשים קלים, מה שלמים נאכלין לשני ימים ולילה אחד, אף בכור נאכל לשני ימים ולילה אחד.\u0004","\u0003אמר לו\u0004 ר' יוסי: \u0003רבי,\u0004 אפשר לומר באופן אחר: \u0003בכור\u0004 הוא \u0003מתנה לכהן, וחטאת ואשם\u0004 אף הם \u0003מתנה לכהן, מה חטאת ואשם\u0004 זמן אכילתם הוא \u0003ליום ולילה, אף בכור ליום ולילה!\u0004","\u0003אמר לו\u0004 ר' טרפון: \u0003נדון דבר מתוך דבר\u0004 הדומה לו, כפי שדנתי, שבכור קדשים קלים הוא כשלמים, \u0003ו\u0004עוד \u0003נלמד דבר מתוך דבר\u0004 כלומר, יש צד נוסף של דמיון, כיצד? \u0003מה שלמים אין באין על חטא, אף בכור אינו בא על חטא,\u0004 ומתוך שני צדדים אלו של דמיון נאמר: \u0003מה שלמים נאכלים לשני ימים ולילה אחד, אף בכור נאכל לשני ימים ולילה אחד.\u0004","\u0003אמר לו\u0004 ר' יוסי: \u0003רבי,\u0004 כך אשיב גם אני: \u0003נדון דבר מדבר ילמד דבר מדבר,\u0004 אבל בדרך אחרת: נדון דבר מדבר — \u0003חטאת ואשם\u0004 הם \u0003מתנה לכהן, ובכור מתנה לכהן,\u0004 ועוד נלמד: \u0003מה חטאת ואשם אין באין בנדר ונדבה, אף בכור אינו בנדר ונדבה.\u0004 ולפיכך נאמר: \u0003מה חטאת ואשם נאכלין ליום אחד, אף בכור נאכל ליום אחד!\u0004","\u0003קפץ ר' עקיבא\u0004 להשיב, \u0003ונסתלק ר' טרפון.\u0004 וכך \u0003אמר לו\u0004 ר' עקיבא לר' יוסי הגלילי: \u0003הרי הוא אומר\u0004 במפורש: \u0003\"ובשרם\u0004 (של הבכורות) \u0003יהיה לך\u0004 כחזה התנופה וכשוק הימין\" (במדבר יח, יח), \u0003הקישן הכתוב לחזה ושוק של שלמים,\u0004 ולפיכך, \u0003מה שלמים נאכלין לשני ימים ולילה אחד, אף בכור נאכל לשני ימים ולילה אחד,\u0004 ואין משיבים מכח סברה על מה שהקישו הכתוב במפורש.","\u0003אמר לו\u0004 ר' יוסי הגלילי: \u0003היקשתו לחזה ושוק של שלמים, ואני מקישו לחזה ושוק של תודה,\u0004 שהרי גם מהם מקבל הכהן חזה ושוק, ואני אומר כך: \u0003מה תודה נאכלת ליום ולילה, אף בכור נאכל ליום ולילה!\u0004","\u0003אמר לו\u0004 ר' עקיבא: הצדק כדבריך, ואולם \u0003הרי הוא אומר: \"ובשרם יהיה לך\u0004 כחזה התנופה וכשוק הימין לך יהיה\" (במדבר יח, יח), \u0003שאין תלמוד לומר\u0004 כלומר, אין לכאורה צורך במה שחוזר הכתוב ואומר: \u0003\"לך יהיה\", ומה תלמוד לומר \"לך יהיה\"? הוסיף הכתוב הויה אחרת בבכור,\u0004 שיהא לו בבכור זמן נוסף שיוכל לאוכלו, כשלמים.","\u0003וכשנאמרו דברים\u0004 אלה בבית המדרש \u0003לפני ר' ישמעאל, אמר להן: צאו ואמרו לו לר' עקיבא: טעיתה\u0004 במה שהודית לר' יוסי הגלילי, שהיה מקום להקיש את הבכור לתודה, שכן \u0003תודה מהיכן למדה\u0004 שחזה ושוק שלה נאכל לכהנים? \u0003משלמים,\u0004 על ידי היקש, שהרי בתודה עצמה לא נזכר כלל דין זה. \u0003וכי\u0004 בקדשים \u0003דבר הלמד בהיקש חוזר ומלמד בהיקש?\u0004 ואם כן בטלה קושייתו של ר' יוסי הגלילי, \u0003הא אין עליך לידון בלשון אחרון\u0004 שלמדת מ\"לך יהיה\", \u0003אלא בלשון ראשון\u0004 שהקיש הכתוב את הבכור לחזה ושוק של שלמים.","ושואלים: \u0003ו\u0004לשיטת \u0003ר' ישמעאל, האי\u0004 \u0005[הכתוב]\u0006 \u0003\"לך יהיה\" מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה בו],\u0006 שהרי לשיטתו הוא מיותר! ומשיבים: \u0003לימד\u0004 כתוב זה \u0003על בכור בעל מום\u0004 שגם \u0003הוא\u0004 ניתן \u0003מתנה לכהן, ש\u0004הרי \u0003לא מצינו בכל התורה\u0004 כולה מפורש מה עושה בבכור בעל מום (שאין מקריבים ממנו למזבח).","ושואלים: \u0003ור' עקיבא,\u0004 מנין למד הוא דין בכור בעל מום? ומשיבים: \u0003יליף ליה\u0004 \u0005[לומד\u0006 דבר \u0005זה]\u0006 \u0003מ\u0004מה שכתוב שם \u0003\"בשרם\"\u0004 בלשון רבים, לומר: \u0003חד\u0004 \u0005[אחד]\u0006 בבכור \u0003תם וחד\u0004 \u0005[ואחד]\u0006 ב\u0003בעל מום.\u0004 ושואלים: \u0003ור' ישמעאל\u0004 כיצד מפרש את לשון הרבים? ומשיבים: \u0003מ\"בשרם\" דהנך\u0004 \u0005[של אותם]\u0006 \u0003בכורות קאמר\u0004 \u0005[הוא אומר]\u0006 (בכור שור, בכור כשב ובכור עז, שנזכרו בפסוק קודם).","ושואלים: הואיל ומוסכם על כולם כי אין למדים היקש מהיקש, \u0003במאי קמיפלגי\u0004 \u0005[במה חלוקים]\u0006 ר' ישמעאל ור' עקיבא? ומסבירים: חלוקים הם בשאלה האם ההיקש של תודה לשלמים נחשב היקש לגבי כלל זה, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' ישמעאל, \u0005סבור]:\u0006 דין הנלמד \u0003הימנו\u0004 (ממנו) מהיקש \u0003ו\u0004מ\u0003דבר אחר,\u0004 כגון כאן, שרק עצם הדין שמפרישים מהתודה חזה ושוק נלמד בהיקש משלמים, אבל זמן האכילה ליום ולילה מקורו בתודה עצמה — \u0003הוי\u0004 \u0005[הרי זה]\u0006 \u0003היקש,\u0004 שאין למדים ממנו בהיקש לבכור. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' עקיבא\u0005,\u0006 \u0005סבור]:\u0006 היקש כזה \u0003לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003היקש\u0004 לענין זה, ויכולים ללמוד דין זה בהיקש.","ושואלים: \u0003בשלמא למאן דאמר לא הוי\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר\u0006 ש\u0005אין זה]\u0006 \u0003היקש,\u0004 ולמדים ממנו בהיקש — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 בעבודת יום הכיפורים: \u0003\"וכן יעשה לאהל מועד\"\u0004 (ויקרא טז, טז), להקיש את הזאת הדם על הפרוכת שבאוהל מועד להזאה שבין בדי הארון בקודש הקדשים, לומר:","\u0003כשם שמזה לפני ולפנים אחת למעלה ושבע למטה מדם הפר, כך מזה\u0004 מדמו אחת למעלה ושבע למטה \u0003בהיכל\u0004 על הפרוכת,","\u0003וכשם שלפני ולפנים\u0004 מזה \u0003אחת למעלה ושבע למטה מדם השעיר, כך מזה בהיכל,\u0004 אף שפרטי ההזאות של דם הפר ושל דם השעיר נלמדו זה מזה בהיקש (\"ועשה את דמו כאשר עשה לדם הפר\". ויקרא טז, טו). וטעם הדבר — משום שבכל אחד נאמרו מקצת ההזאות, ורק חלק נלמד מן ההיקש, והוא \"הימנו ודבר אחר\".","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי הימנו ודבר אחר \u0003הוי\u0004 \u0005[הרי זה]\u0006 \u0003היקש מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 כיצד יכול ללמוד בהיקש על ההיכל, ממה שנלמד בהיקש לפני ולפנים? ומשיבים: שם לא הדבר הנלמד בהיקש חוזר ונלמד בהיקש, שהרי בהיקש הראשון הוקשו דם הפר ודם השעיר, ואילו בהיקש השני \u0003מקומות הוא דגמרי מהדדי\u0004 \u0005[הם שלמדים זה מזה]\u0006 שיהא דינם שווה."],["\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי בהיקש השני לא פרטים מסויימים נלמדים על ידי ההיקש, אלא יש כאן היקש כללי: \"וכן יעשה לאהל מועד\", ובו כל הענין של \u0003חוץ מפנים בחד זימנא גמיר\u0004 \u0005[בבת אחת הוא לומד],\u0006 ואגב כך נלמדים כל פרטי ההלכות, מכל מקור שהוא. ושואלים עוד: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 שהימנו ודבר אחר \u0003[לא] הוי\u0004 \u0005[אין זה]\u0006 \u0003היקש,\u0004 וניתן ללמוד דין זה בהיקש לדבר אחר, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 בשתי הלחם: \u0003\"ממושבתיכם תביאו לחם תנופה\u0004 שתים שני עשרונים סלת תהיינה חמץ תאפינה\" (ויקרא כג, יז), ואמרו בברייתא: \u0003שאין תלמוד\u0004 (צריך) \u0003לומר \"תביאו\",\u0004 שהרי כבר נאמר מתחילה \"והקרבתם\" (ויקרא כג, טז), \u0003מה תלמוד לומר \"תביאו\"?\u0004 לומר: \u0003כל שאתה מביא ממקום (למקום) אחר\u0004 כעין זה, כלומר, לחם חמץ — \u0003הרי הוא כזה, מה להלן\u0004 בשתי הלחם \u0003עשרון\u0004 קמח \u0003ל\u0004כל \u0003חלה,\u0004 שנאמר \"שתים — שני עשרונים\", ומכאן שללחם אחד עשרון אחד, \u0003אף כאן,\u0004 בכל אחד מעשר לחמי חמץ שבתודה, \u0003עשרון לחלה.\u0004","","","ושואלים: \u0003אי\u0004 \u0005[או]\u0006 נלמד אחרת: \u0003מה להלן,\u0004 בשתי הלחם, הכמות היא \u0003שני עשרונים, אף כאן,\u0004 בלחמי חמץ שבתודה, אינו מביא אלא \u0003שני עשרונים\u0004 לכל עשר החלות! \u0003תלמוד לומר: \"תהיינה\"\u0004 — למעט ולומר כי דווקא שתי הלחם באות שני עשרונים, ולא החמץ שבתודה. על כל פנים למדנו שצריך עשרה עשרונים לחמץ שבתודה, הימנו ודבר אחר — ממה שנאמר בו שהוא צריך לבוא עשר חלות, ומן ההיקש לשתי הלחם. ודין זה עצמו חוזר ונלמד בהיקש, כפי שממשיכה הברייתא.","\u0003ולמדנו\u0004 כי \u0003עשרה\u0004 עשרונים מביא \u0003לחמץ\u0004 שבתודה, \u0003עשרה\u0004 עשרונים \u0003למצה\u0004 שבה \u0003מנין? תלמוד לומר\u0004 \"והקריב... חלות מצות... \u0003על חלת לחם חמץ\"\u0004 (ויקרא ז, יג), להקיש את המצה לחמץ, לומר: \u0003נגד חמץ הבא מצה,\u0004 באותו שיעור.","\u0003אלא למאן דאמר (לא) הוי\u0004 \u0005[ל\u0006דעת \u0005מי שאומר\u0006 כי הימנו ודבר אחר \u0005הרי זה]\u0006 \u0003היקש,\u0004 ולא ניתן לחזור וללמוד דין זה בהיקש, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 כיצד למדים מחמץ שבתודה למצה שבה? ומשיבים: הלימוד הראשון, משתי הלחם לחמץ שבתודה, איננו לימוד בהיקש, אלא מריבוי הכתובים, כי המילה \u0003\"תביאו\"\u0004 שבשתי הלחם \u0003יתירא היא,\u0004 וכאילו נאמר הדבר במפורש לגבי לחם חמץ שבתודה, שהוא בא עשרון לחלה, ולכן אפשר ללמוד ממנו בהיקש.","שנינו במשנה: \u0003הפסח אינו נאכל\u0004 אלא עד חצות. ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן? \u0003אמר רב יוסף:\u0004 שיטת \u0003ר' אלעזר בן עזריה היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעזר בן עזריה אומר: נאמר כאן:\u0004 \"אכלו את הבשר \u0003בלילה הזה\"\u0004 (שמות יב, ח), \u0003ונאמר להלן: \"ועברתי בארץ מצרים בלילה הזה\"\u0004 (שמות יב, יב),","\u0003מה להלן\u0004 \"ועברתי\" הוא \u0003עד חצות\u0004 ולא לאחר מכן, שנאמר \"ויהי בחצי הלילה וה' הכה כל בכור\" וכו' (שמות יב, כט), \u0003אף כאן\u0004 לגבי אכילה זמנה \u0003עד חצות.\u0004 \u0003אמר לו ר' עקיבא, והלא כבר נאמר: \"ואכלתם אותו בחפזון\"\u0004 (שמות יב, יא), לומר \u0003עד שעת חפזון\u0004 שנחפזו לצאת, ודבר זה לא היה אלא בבוקר, שנאמר \"ואתם לא תצאו מפתח ביתו עד בוקר\" (שמות יב, כב)! \u0003אם כן, מה תלמוד לומר\u0004 בכל זאת \u0003\"בלילה הזה\"?\u0004 ללמד דבר אחר, \u0003שיכול יהא\u0004 הפסח \u0003כ\u0004שאר \u0003כל הקדשים הנאכלים\u0004 כבר מיד \u0003ביום\u0004 שחיטתו כלומר, בארבעה עשר בניסן? \u0003תלמוד לומר \"בלילה\",\u0004 לומר ולהדגיש: \u0003בלילה\u0004 דווקא \u0003יהא נאכל, ואינו נאכל ביום.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003וממאי\u0004 \u0005[וממה]\u0006 אתה יודע שמשנתנו שיטת \u0003ר' אלעזר בן עזריה\u0004 היא, \u0003ודאורייתא\u0004 \u0005[ומדין תורה]\u0006 הוא רק עד חצות? \u0003דלמא\u0004 \u0005[שמא]\u0006 מדין תורה זמנו עד הבוקר, כר' עקיבא, ומה שנאמר עד חצות — אין זה אלא גזירה \u0003דרבנן\u0004 \u0005[של חכמים],\u0006 \u0003כדי\u0004 \u0003להרחיק\u0004 האדם \u0003מן העבירה!\u0004 ודוחים: \u0003אם כן, מאי\u0004 \u0005[מה]\u0006 משמעות המלים \u0003\"אלא עד חצות\"?\u0004 והרי בשאר קרבנות שנינו רק \"עד חצות\". \u0003אלא\u0004 צריכים לומר שהוא \u0003כי התם\u0004 \u0005[כמו שם],\u0006 בשאר דיני הפסח הנזכרים בלשון זו (אינו נאכל אלא למנוייו, אינו נאכל אלא צלי), \u0003מה התם\u0004 \u0005[שם]\u0006 הוא \u0003דאורייתא\u0004 \u0005[דין תורה\u0006 הוא\u0005],\u0006 \u0003אף כאן נמי דאורייתא\u0004","","","",""],["\u0003קדשי קדשים,\u0004 שנאמר בראש הפרק הקודם ששחיטתם בצפון, \u0003ששחטן בראש המזבח\u0004 — \u0003ר' יוסי אומר: כאילו נשחטו בצפון. ר' יוסי בר' יהודה אומר: מחצי\u0004 (מאמצע) \u0003המזבח ולדרום\u0004 — \u0003כדרום, מחצי המזבח ולצפון\u0004 — \u0003כצפון.\u0004","\u0003אמר רב אסי אמר ר' יוחנן, אומר היה ר' יוסי: כוליה\u0004 \u0005[כל]\u0006 ה\u0003מזבח\u0004 כולו \u0003בצפון\u0004 העזרה \u0003קאי\u0004 \u0005[הוא עומד].\u0006 ושואלים: אם כן, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 מה שנאמר במשנתנו שקדשי קדשים שנשחטו בראש המזבח \u0003כאילו\u0004 נשחטו בצפון העזרה? הרי נשחטו בצפון ממש! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיקיים בשחיטה גם את התנאי \u0003\"על ירך\u0004 המזבח\" (ויקרא א, יא), \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי אין זה בצד המזבח, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שגם כך כשר הדבר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לרב אסי:\u0004 מדברי ר' יוחנן עולה כי משום שהמזבח כולו בצפון, לכן שחיטת קדשי קדשים בראשו כשרה. \u0003אלא מעתה, לר' יוסי בר' יהודה,\u0004 שאמר כי מחציו של המזבח לדרום כדרום, ומחציו ולצפון כצפון, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 נאמר, שלדעתו \u0003חציו\u0004 של המזבח \u0003בצפון וחציו בדרום\u0004 ממש?","\u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך הוא גם כן],\u0006 \u0003והא את\u0004 \u0005[והרי אתה]\u0006 עצמך \u0003הוא דאמרת משמיה\u0004 \u0005[שאמרת משמו]\u0006 של \u0003ר' יוחנן: מודי\u0004 \u0005[מודה]\u0006 \u0003רבי יוסי בר' יהודה שאם שחטן\u0004 את קדשי הקדשים \u0003כנגדן\u0004 כנגד אותו מקום \u0003בקרקע,\u0004 מחצי המזבח וצפונה — \u0003פסולה,\u0004 ואם כן לשיטתו אין המזבח מצוי בצפון כלל!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אסי: דברי ר' יוחנן, שלדעת ר' יוסי המזבח כולו מצוי בצפון, לא נאמרו כהסבר לדעתו במשנתנו, אלא כענין לעצמו. ובטעמה של המחלוקת שבמשנה \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 \u0003ר' יוחנן: שניהם,\u0004 ר' יוסי ור' יוסי בר' יהודה, \u0003מקרא אחד דרשו,\u0004 שנאמר: \"מזבח אדמה תעשה לי \u0003וזבחת עליו את עלתיך ואת שלמיך\"\u0004 (שמות כ, כא),","\u0003ר' יוסי סבר\u0004 \u0005[סבור]:\u0006 הכוונה היא שהמזבח \u0003כולו\u0004 כשר \u0003ל\u0004שחיטת \u0003עולה וכולו\u0004 כשר \u0003לשלמים. ורבי יוסי בר' יהודה סבר\u0004 \u0005[סבור]:\u0006 מפסוק זה למדים ש\u0003חציו לעולה וחציו לשלמים.\u0004","וטעמו, \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 ש\u0003כולו לעולה כשר,\u0004 אם כן מדוע היה צורך להזכיר ששוחטים עליו גם עולה וגם שלמים? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003כולו לעולה כשר,\u0004 למרות שדינה להישחט דווקא בצפון, \u0003כולו לשלמים מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006 והרי שלמים כשרים לשחיטה בכל העזרה! אלא הוזכרו גם שלמים כדי לומר שיש חלק במזבח בו ניתן לזבוח רק שלמים.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 ר' יוסי, מה הוא משיב על כך? מדוע הוזכרו שלמים? ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003עולה הוא דדחיק ליה\u0004 \u0005[שדחוק לה]\u0006 ה\u0003מקום,\u0004 שהרי אינה נשחטת אלא בצפון, ואולי משום כך מותר גם לשוחטה על המזבח עצמו, \u0003אבל שלמים\u0004 ש\u0003לא דחיק ליה\u0004 \u0005[דחוק להם]\u0006 ה\u0003מקום\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא, קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שכשר הדבר.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של הלכה שהזכרנו, \u0003אמר רב אסי אמר ר' יוחנן: מודי\u0004 \u0005[מודה]\u0006 \u0003ר' יוסי בר' יהודה שאם שחטן\u0004 קדשי קדשים \u0003כנגדן\u0004 כנגד חציו הצפוני של המזבח, אבל \u0003בקרקע\u0004 — \u0003פסולות. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא:\u0004 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הדברים שאמר \u0003\"כנגדן בקרקע\"? אילימא\u0004 \u0005[אם תאמר]\u0006 ששחטם על גבי רוחב \u0003אמה\u0004 של \u0003יסוד\u0004 המזבח, או על גבי רוחב \u0003אמה סובב\u0004 (המדריגה המצויה למעלה מחציו של המזבח), הרי \u0003האי גופיה\u0004 \u0005[זה עצמו]\u0006 \u0003מזבח הוא! ועוד,\u0004 אם תפרש כך, \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 \u0003\"כנגדן בקרקע\"?\u0004 הרי אין זה בקרקע!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\"כנגדן בקרקע\" כוונתו \u0003דעביד\u0004 \u0005[שעושה]\u0006 \u0003מחילות בקרקע\u0004 מתחת למזבח, \u0003ושחיט בהו\u0004 \u0005[ושוחט בהם],\u0006 על כך יש להקשות: \u0003וכי האי גוונא מי הוי\u0004 \u0005[ו\u0006מזבח \u0005כגון זה האם\u0006 הוא בכלל \u0005נחשב]\u0006 ל\u0003מזבח? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"מזבח אדמה תעשה לי\"\u0004 (שמות כ, כא) — \u0003שיהא מחובר מאדמה, שלא יבננו לא על גבי מחילות ולא על גבי כיפין\u0004 (קשתות)!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא למקרה \u0003דבצריה בצורי\u0004 \u0005[שמיעט אותו]\u0006 את גודל המזבח, ובאותה קרקע שהיתה פעם צפונו של מזבח שחט.","ושבים לדון בעיקר דברי ר' יוחנן, שלדעת ר' יוסי המזבח כולו בצפון עומד, ונתברר כי ר' יוחנן אינו מסתמך על דברי ר' יוסי במשנתנו. \u0003אמר ר' זירא:\u0004 וכי \u0003אפשר איתא להא\u0004 \u0005[שישנו למה]\u0006 שאמר \u0003ר' יוחנן ולא תנינא לה במתניתין\u0004 \u0005[שנינו\u0006 את הדבר \u0005הזה במשנה]?\u0006","\u0003נפק דק ואשכח\u0004 \u0005[יצא\u0006 מחוץ לבית המדרש \u0005דקדק ומצא],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה במסכת תמיד\u0005]:\u0006 \u0003ביררו משם\u0004 (מלשכת העצים) \u0003עצי תאינה יפים לסדר\u0004 על גבי המזבח \u0003מערכה שניה של\u0004 עצים ל\u0003קטרת\u0004 כלומר, שממנה היו נוטלים גחלים להבעיר בהם את הקטורת. והיה מקום מערכה זו \u0003כנגד קרן מערבית דרומית\u0004 של המזבח, \u0003משוך מן הקרן כלפי צפון ארבע אמות.\u0004 ומסדרים שם עצים \u0003באומד\u0004 (שלפי האומדן ניתן להפיק מהם) \u0003חמש סאין גחלים, ובשבת\u0004 מסדרים שם עצים \u0003באומד שמונה סאין גחלים,\u0004 משום \u0003ששם\u0004 על אותה מערכה \u0003היו נותנין\u0004 בשבת \u0003שני בזיכי לבונה של לחם הפנים.\u0004 עד כאן לשון המשנה.","\u0003ומאי סימנא\u0004 \u0005[ומה הסימן]\u0006 כלומר, מהו עניינו של סימן זה שניתן למקום המערכה של הקטורת ולהקטרת בזיכי הלבונה? דבר זה לשיטת \u0003ר' יוסי היא,\u0004 שמדגיש כי שני אלו צריכים להיעשות דווקא במקום מסויים זה, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006"],["\u0003ר' יוסי אומר, זה\u0004 ה\u0003סימן\u0004 יהא בידך: \u0003כל\u0004 דבר \u0003הניטל בפנים\u0004 בהיכל, על מנת \u0003לינתן בחוץ\u0004 על המזבח — \u0003אינו נותן\u0004 אותו במזבח \u0003אלא בסמוך\u0004 לו \u0003שאין לפנים\u0004 יותר ממנו, כלומר במקום הסמוך ביותר לפתח ההיכל.","\u0003ו\u0004כיוצא בזה \u0003כל הניטל בחוץ\u0004 על המזבח, על מנת \u0003לינתן לפנים\u0004 — \u0003אינו ניטל\u0004 מן המזבח \u0003אלא ב\u0004מקום שהוא \u0003סמוך\u0004 לפנים \u0003שאין לפנים\u0004 ממנו.","ומבררים: \u0003\"כל הניטל בפנים לינתן בחוץ\" מאי ניהו\u0004 \u0005[מהו זה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר ב\u0003שירים\u0004 של החטאות הפנימיות, \u0003הרי\u0004 \u0003בהדיא כתיב בהו\u0004 \u0005[במפורש נאמר בהם]:\u0006 \u0003\"אל יסוד מזבח העלה אשר פתח אהל מועד\"\u0004 (ויקרא ד, ז), שצריך לשופכם על היסוד המערבי, הסמוך לפתח, ומדוע צריך ר' יוסי לתת סימן לדבר?","\u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003\"כל הניטל בחוץ לינתן בפנים\" מאי ניהו\u0004 \u0005[מהו הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהם \u0003גחלים של יום הכיפורים,\u0004 שצריך ליטלם מצידו המערבי של המזבח — הלוא \u0003בהדיא כתיב בהו\u0004 \u0005[במפורש כתוב בהם]:\u0006 \u0003\"ולקח מלא המחתה גחלי אש\u0004 מעל המזבח מלפני ה'\" (ויקרא טז, יב), והוא הצד המערבי, הקרוב להיכל!","\u0003אלא\u0004 כך צריך לפרש: \u0003כל הניטל בפנים לינתן בחוץ\u0004 אלה הם \u0003שני בזיכי לבונה של לחם הפנים,\u0004 שסבור ר' יוסי שצריך להקטירם בצד המערבי של המזבח החיצון. וטעמו, \u0003דגמרי\u0004 \u0005[ש\u0006הם \u0005למדים]\u0006 \u0003משירים\u0004 של דם החטאות הפנימיות, ושם נאמרו הדברים במפורש, כפי שנתבאר לעיל.","ומה שנאמר \u0003הניטל בחוץ לינתן בפנים\u0004 הם \u0003גחלים דכל יומא ויומא\u0004 \u0005[של כל יום ויום],\u0006 שמכניסים מהם להקטיר קטורת על מזבח הזהב, \u0003דגמרן\u0004 \u0005[שלמדים]\u0006 \u0003מגחלים של יום הכפורים,\u0004 שנאמר בהם הדבר במפורש, כפי שנתבאר לעיל. הרי שר' יוסי נזקק לתת סימן למקומה של המערכה השניה לקטורת, ולומר גם כי שם מקטירים את בזיכי הלבונה, והוא כפי שעשה התנא במסכת תמיד, ומכאן שאותה משנה נאמרה לשיטתו.","ומעתה נברר, \u0003ומאי קסבר\u0004 \u0005[ומה\u0006 הוא \u0005סבור]?\u0006 \u0003אי קסבר\u0004 \u0005[אם\u0006 הוא \u0005סבור]:\u0006 \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003מזבח\u0004 כולו \u0003בדרום\u0004 העזרה \u0003קאי\u0004 \u0005[הוא עומד],\u0006 מאמצע העזרה ולדרום, נמצא שממול פתח ההיכל (המצוי בדיוק באמצע העזרה) שרוחבו עשר אמות, מצויות רק חמש האמות הצפוניות של המזבח, והואיל ואורכו של המזבח שלושים ושתים אמות, הרי אם רוצה לסדר את המערכה מול הפתח — \u0003עשרים ושבע\u0004 אמות \u0003בעי למיתי\u0004 \u0005[צריך להיכנס]\u0006 מקצהו הדרומי של המזבח, ולא ארבע, כפי ששנינו","\u0003!\u0004 \u0003ואי נמי קסבר\u0004 \u0005[ואם גם כן סבור הוא]:\u0006 \u0003קדושת\u0004 ה\u0003היכל ו\u0004קדושת ה\u0003אולם\u0004 העומד בחזית ההיכל \u0003חדא\u0004 \u0005[\u0006קדושה \u0005אחת]\u0006 \u0003היא,\u0004 ויכול לסדר את המערכה מול פתחו של האולם, שרוחבו עשרים אמה, חמש אמות נוספות לכל צד מעבר לפתחו של ההיכל, על כל פנים \u0003עשרים ותרתי\u0004 \u0005[ושתים]\u0006 אמות \u0003בעי מיתי\u0004 \u0005[צריך להיכנס]\u0006 מקצהו הדרומי של המזבח!","\u0003ואי קסבר\u0004 \u0005[ו\u0006גם \u0005אם סבור הוא]\u0006 שהמזבח \u0003חציו בצפון\u0004 העזרה \u0003וחציו בדרום\u0004 כלומר, שש עשרה אמה לכל צד, בכל זאת \u0003חד סרי בעי למיתי\u0004 \u0005[אחת עשרה\u0006 אמות \u0005צריך להיכנס]\u0006 מקצהו הדרומי כדי שתהיה המערכה מול פתח ההיכל! \u0003ואלא\u0004 תאמר \u0003קסבר\u0004 \u0005[\u0006ש\u0005סבור הוא]:\u0006 \u0003קדושת היכל ואולם חדא מילתא היא\u0004 \u0005[דבר אחד הוא],\u0006 ופתחו של אולם מוסיף חמש אמות נוספות בדרום, על כל פנים \u0003שית בעי למיתי\u0004 \u0005[שש\u0006 אמות \u0005צריך להיכנס]\u0006 מקצה המזבח, ולא ארבע!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 נאמר כי טעם הדבר \u0003משום דקסבר\u0004 \u0005[שהוא סבור]:\u0006 \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003מזבח בצפון קאי\u0004 \u0005[\u0006הוא \u0005עומד]\u0006 מאמצע העזרה וצפונה, ולפיכך רק חמש אמות דרומיות שלו נמצאות מול פתח ההיכל,","\u0003והני\u0004 \u0005[ואותן]\u0006 \u0003ארבע אמות\u0004 שהמערכה מרוחקת מן הקצה הדרומי, הרי הן \u0003אמה יסוד ואמה סובב, ואמה מקום קרנות, ואמה מקום\u0004 להילוך \u0003רגלי הכהנים\u0004 בעבודתם. ודווקא שם היתה המערכה משום \u0003דכי מסגו לקמיה טפי\u0004 \u0005[שאם ירחיקו יותר,\u0006 צפונה, אפילו \u0005אמה אחת נוספת\u0006\u0005]\u0006 \u0003תו ליכא\u0004 \u0005[שוב אין]\u0006 זה מול ה\u0003פתח.\u0004 נמצאת איפוא משנה כשיטת ר' יוסי, וממנה מוכח כי כל המזבח הוא בצד צפון, וכדברי ר' יוחנן.","\u0003אמר רב אדא בר אהבה:\u0004 ניתן לדחות את ראייתו של ר' זירא, ולומר: \u0003הא מני\u0004 \u0005[זו,\u0006 המשנה במסכת תמיד, \u0005כשיטת\u0006 \u0005מי היא]?\u0006 שיטת \u0003ר' יהודה היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: מזבח ממוצע ועומד באמצע העזרה,\u0004 חציו בצפון וחציו בדרום, \u0003ושלשים ושתים אמות היו לו, עשר אמות כנגד פתחו של היכל, אחת עשרה אמה מיכן,\u0004 מדרום, \u0003ואחת עשרה אמה מיכן,\u0004 מצפון, \u0003נמצא\u0004 אורכו של \u0003מזבח מכוון כנגד\u0004 רוחבו של \u0003היכל,\u0004 שהיה אף הוא שלושים ושתים אמות.","ושואלים: \u0003סוף סוף לר' יהודה חד סרי בעי למיתי\u0004 \u0005[אחת עשרה\u0006 אמות \u0005צריך להיכנס]\u0006 לכיוון צפון, ולא ארבע, כפי שהוכחנו. \u0003ואי קסבר\u0004 \u0005[ו\u0006גם \u0005אם סבור הוא]:\u0006 \u0003קדושת היכל ואולם חדא מילתא היא\u0004 \u0005[דבר אחד הוא],\u0006 וניתן לסדר את המערכה מול פתח ההיכל שהיה רחב חמש אמות נוספות לכל צד, על כל פנים \u0003שית בעי למיתי\u0004 \u0005[שש\u0006 אמות \u0005צריך להיכנס],\u0006 ולא ארבע!","ומשיבים: \u0003מי סברת הני\u0004 \u0005[האם סבור אתה שאותן]\u0006 \u0003ארבע אמות\u0004 שאמרנו שצריך להתקדם כלפי צפון, הריהו \u0003בהדי\u0004 \u0005[יחד עם,\u0006 כוללים בתוכם\u0005]\u0006 \u0003אמה יסוד ואמה סובב?\u0004 לא, \u0003ארבע אמות\u0004 שאמרנו הן \u0003בר\u0004 \u0005[חוץ]\u0006 \u0003מאמה יסוד ואמה סובב.\u0004 כי מחשבים אותן ארבע אמות מקצהו הדרומי של ראש המזבח, ונמצא מקום המערכה מדוייק כנגד ההיכל. ושואלים: ומדוע צריך רב אדא בר אהבה להעמיד משנה זו כר' יהודה?","\u0003ונוקמה\u0004 \u0005[ונעמידה]\u0006 \u0003כ\u0004דעת \u0003ר' יוסי, ו\u0004נאמר שלדעתו המזבח \u0003בממוצע\u0004 (באמצע), וארבע אמות שהוזכרו אינן כוללות אמה יסוד ואמה סובב! ומשיבים: \u0003משום\u0004 ש\u0003ר' יהודה שמענא ליה ממוצע בהדיא\u0004 \u0005[שמענו אותו במפורש\u0006 אומר שמזבח היה \u0005ממוצע],\u0006 ואין ראיה שכך היא גם שיטת ר' יוסי.","\u0003ורב שרביא אמר: הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' יוסי הגלילי היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יוסי הגלילי אומר, מתוך שנאמר: \"ונתת את הכיור בין אהל מועד\u0004 ובין המזבח\" \u0003וגומר\u0004 (שמות מ, ז), ומצד אחר נאמר: \u0003\"ואת\u0004"],["\u0003מזבח העלה\u0004 שם פתח משכן אהל מועד\" וגו' (שמות מ, כט), ומשם יש לדייק: \u0003מזבח\u0004 נמצא \u0003בפתח אהל מועד, ולא כיור בפתח אהל מועד,\u0004 אם כן \u0003היכן היה נותנו\u0004 את הכיור במקדש — \u0003בין האולם ולמזבח,\u0004 אבל לא בדיוק מול המזבח, אלא \u0003משוך קימעא כלפי הדרום.\u0004","ונברר: \u0003מאי קסבר\u0004 \u0005[מה סבור]\u0006 ר' יוסי הגלילי? \u0003אי קסבר\u0004 \u0005[אם סבור הוא]:\u0006 \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003מזבח בדרום קאי\u0004 \u0005[\u0006הוא \u0005עומד],\u0006 כלומר, מאמצע העזרה לדרום — מדוע משוך הכיור מדרום למזבח? \u0003נוקמיה\u0004 \u0005[שיעמיד אותו]\u0006 \u0003מכותל\u0004 ה\u0003היכל ולדרום,\u0004 כלומר, מדרום לפתח, \u0003בין אולם למזבח!\u0004","\u0003ואי נמי קסבר\u0004 \u0005[ואם גם כן סבור הוא]:\u0006 \u0003קדושת היכל ואולם חדא\u0004 \u0005[אחת]\u0006 \u0003היא,\u0004 וגם מול פתחו של האולם, שהוא רחב חמש אמות נוספות לדרום, אינו יכול לתת את הכיור — \u0003נוקמיה\u0004 \u0005[שיעמיד אותו]\u0006 \u0003מכותל אולם ולדרום\u0004 כלומר, מדרום לפתח האולם \u0003בבין אולם למזבח!\u0004","\u0003אי נמי קסבר\u0004 \u0005[אם גם כן סבור]:\u0006 המזבח נמצא \u0003חציו בצפון וחציו\u0004 \u0003בדרום,\u0004 שש עשרה אמה לכל צד, \u0003נוקמיה\u0004 \u0005[שיעמיד אותו\u0006 את הכיור\u0005]\u0006 \u0003מכותל היכל ולדרום\u0004 כלומר, מדרום לפתח ההיכל, \u0003בין אולם ולמזבח,\u0004 שהרי נותרו לשם כך אחת עשרה אמות באורך המזבח!","\u0003ואי נמי קסבר\u0004 \u0005[ואם גם כן סבור הוא]:\u0006 \u0003קדושת האולם והיכל חדא\u0004 \u0005[אחת]\u0006 \u0003היא,\u0004 והשטח העומד לרשותו קטן בחמש אמות נוספות של פתח האולם — \u0003נוקמיה\u0004 \u0005[שיעמיד אותו]\u0006 \u0003מכותל אולם ולדרום בין אולם ולמזבח,\u0004 שהרי עומדות לרשותו שש אמות לצורך זה. ומדוע צריך למשוך את הכיור מדרום למזבח? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דקסבר\u0004 \u0005[שסבור הוא]\u0006 ר' יוסי הגלילי \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003מזבח\u0004 עומד \u0003בצפון\u0004 מול אמצע פתח ההיכל וצפונה. ולכן, כדי שלא יעמוד הכיור מול הפתח צריך למושכו דרומה למזבח.","ושואלים: \u0003כי נמי מוקמת לה\u0004 \u0005[גם כאשר אתה מעמיד אותה]\u0006 \u0003מכותל היכל ולצפון\u0004 כלומר, מצפון לפתח ההיכל, \u0003הוה ליה\u0004 \u0005[הרי הוא]\u0006 \u0003בין אולם ולמזבח,\u0004 ואם כן, מפני מה מושכו לדרום?","\u0003ונוקמה\u0004 \u0005[ויעמיד אותו]\u0006 \u0003מכותל אולם ולצפון בבין אולם ולמזבח!\u0004","ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"ושחט אותו על ירך המזבח \u0003צפונה\"\u0004 (ויקרא א, יא), לומר \u0003שיהא צפון פנוי מכלים\u0004 לצורך השחיטה. הוזכרה בדיון זה הדעה שהמזבח כולו בדרום.","ושואלים: \u0003מאן\u0004 \u0005[מי]\u0006 הוא ה\u0003תנא דפליג עליה\u0004 \u0005[שחולק עליו]\u0006 על \u0003ר' יוסי הגלילי\u0004 וסבור כן? \u0003ר' אליעזר בן יעקב היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר:\u0004 נאמר \u0003\"צפונה\u0004 לפני ה'\" (ויקרא א, יא) לומר — \u0003שיהא צפון פנוי מכלום, ואפילו מן המזבח,\u0004 שגם המזבח לא היה בצפון. ומכאן שהוא סבור שהמזבח כולו בדרום.","\u0003אמר רב: מזבח שנפגם\u0004 — \u0003כל הקדשים שנשחטו שם פסולין.\u0004 והוסיף רב: \u0003מקרא הוא בידינו ושכחנוהו\u0004 כלומר, יודע אני ראיה לדבר מן המקרא, אלא ששכחתי מהו המקרא הזה. \u0003מסופר,\u0004 \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003רב כהנא\u0004 תלמידו של רב לארץ ישראל, \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003ר'\u0004 \u0003שמעון ברבי דקאמר\u0004 \u0005[שהוא אומר]\u0006 \u0003משום\u0004 (בשם) \u0003ר' ישמעאל בר' יוסי: מנין למזבח שנפגם שכל הקדשים שנשחטו שם פסולין?\u0004","\u0003שנאמר: \"וזבחת עליו את עלתיך ואת שלמיך\"\u0004 (שמות כ, כא), \u0003וכי עליו\u0004 על המזבח \u0003אתה זובח\u0004 (שוחט)? הלא אתה זובח בצידו! \u0003אלא\u0004 \"עליו\" במובן בגללו, כאשר יש מזבח, \u0003כשהוא שלם ולא כשהוא חסר. אמר\u0004 רב כהנא: \u0003היינו קרא דאישתמיט ליה\u0004 \u0005[זהו הפסוק שנשמט לו]\u0006 \u0003לרב.\u0004","\u0003ור' יוחנן אמר: אחד זה ואחד זה פסולין\u0004 כלומר, לא רק קרבנות שנשחטו בזמן פגימת המזבח, אלא גם קרבנות חיים שעמדו להקרבה באותה שעה — פסולים. ומסבירים: \u0003במאי פליגי\u0004 \u0005[במה,\u0006 באיזה עקרון הם \u0005חלוקים]?\u0006 \u0003רב סבר\u0004 \u0005[סבור]:\u0006 \u0003בעלי חיים אינן נדחים\u0004 שכל זמן שהם חיים אין הם נחשבים כדחויים, ואף שנפגם המזבח לא נדחו מהקרבה למזבח. \u0003ור' יוחנן סבר\u0004 \u0005[סבור]:\u0006 \u0003בעלי חיים נידחין,\u0004 וכיוון שהיו אלו קרבנות העומדים להקרבה ונדחו — שוב אין להם תקנה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב, ממה ששנו בברייתא: \u0003כל הקדשים שהיו עד שלא נבנה המזבח, ואחר כך נבנה המזבח\u0004 — \u0003פסולין\u0004 הם. ואנו סבורים שהכוונה היא לקרבנות שהקדישו לפני בנין המזבח של הבית השני. ויש לתמוה: \u0003אם\u0004 \u0003נבנה\u0004 כלומר, שקודם לא היה מזבח כלל, הרי \u0003דחויין מעיקרא נינהו\u0004 \u0005[מתחילה הם],\u0006 והכל מודים שבכגון זה אינם נחשבים דחויים!","\u0003אלא\u0004 יש לתקן כך, אם \u0003עד שלא נהרס המזבח\u0004 בחורבן הבית הראשון, הוקדשו הקרבנות והיו אז ראויים להקרבה, ואחר כך נהרס המזבח ונדחו, הרי משנבנה המזבח בבית השני — פסולים הם. אלא שגם על פירוש זה יש לתמוה: אם הוקדשו קודם ש\u0003נהרס, הא איזקון להו\u0004 \u0005[הרי הזדקנו\u0006 הקרבנות\u0005]\u0006 עד שנבנה הבית השני, וממילא אינם ראויים להקרבה, גם אם לא נהרס המזבח!","\u0003אלא\u0004 יש לתקן: הקדישם (בזמן הבית השני) \u0003עד שלא נפגם המזבח, ואחר כך נפגם המזבח\u0004 — \u0003פסולין.\u0004 משמע שאף בעלי חיים נדחים בכגון זה, ולא רק אלו שנשחטו! ודוחים: \u0003ולא תרוצי קא מתרצת\u0004 \u0005[והאם אינך מיישב\u0006 את הברייתא הזו \u0005ומתקן\u0006 את לשונה\u0003\u0005]\u0006?\u0004 אם כן, תקן עוד קצת, \u0003אימא\u0004 \u0005[אמור]:\u0006 כל הקדשים \u0003שנשחטו\u0004 עד שלא נפגם המזבח, ונפגם המזבח — פסולים. ואם כן, אין מכאן ראיה לגבי בעלי חיים שהם נידחים.","ומקשים: וכי לדעת רב מזבח שנפגם פוסל את ההקרבה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב גידל אמר רב: מזבח\u0004 הזהב \u0003שנעקר\u0004 ממקומו — \u0003מקטירין קטרת במקומו.\u0004 הרי שהמזבח אינו מעכב!","ומשיבים, \u0003כ\u0004מו \u0003ש\u0004\u0003אמר רבא:\u0004 למרות שכל העזרה כשרה להקטרת אימורים, כמו המזבח, \u0003מודה היה ר' יהודה ב\u0004זריקת \u0003דמים\u0004 שצריך לזרוק דווקא על המזבח, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003מודה רב בדמים,\u0004 הואיל ולגבי זריקת הדם חייבים שיהא מזבח, הרי כששוחטים כשהמזבח פגום נדחה הדם מזריקה, והקרבן פסול.","כיון שהוזכרה שיטת ר' יהודה, שואלים: \u0003מאי\u0004 \u0005[מהם]\u0006 דברי \u0003ר' יהודה? דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר בחנוכת המקדש שבימי שלמה \u0003\"ביום ההוא קידש המלך תוך החצר וגו' כי מזבח (שעשה משה) קטן מהכיל\"\u0004 (ראה מלכים א ח, סד), ובפירוש הפסוק הזה נחלקו חכמים, שיש מי שאומר: \u0003דברים\u0004 אלו יש להבין \u0003ככתבן,\u0004 שהמזבח שנבנה במקדש היה קטן מכדי להכיל את כל הקרבנות שהביא שלמה, ושלמה קידש לשם כך את החצר כולה. אלו \u0003דברי ר' יהודה.\u0004","\u0003אמר לו ר' יוסי:\u0004"],["וכי לא היה די במזבח שבנה שלמה? \u0003והלא כבר נאמר\u0004 לגבי המזבח שעשה משה: \u0003\"אלף עלות יעלה שלמה על המזבח ההוא\"\u0004 (מלכים א ג, ד), כשהקריב בבמה שבגבעון, קודם שבנה את המקדש. \u0003ואילו\u0004 במזבח שבנה שלמה \u0003בבית עולמים הוא אומר: \"ויזבח שלמה את זבח השלמים אשר זבח לה' בקר עשרים ושנים אלף\u0004 וצאן מאה ועשרים אלף\" (מלכים א ח, סג).","\u0003וכשאתה מגיע לחשבון עולות ולמנין אמות,\u0004 כמה קרבנות הוקרבו לכל אמה במזבח — \u0003זה גדול מזה\u0004 שבמזבח של משה הוקרבו יותר קרבנות לכל אמה. ואם כן, לא היה המזבח שבנה שלמה קטן מהכיל את הקרבנות שהוקרבו בחנוכת המקדש!","\u0003אלא מהו\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 המלים \"כי מזבח הנחושת... \u0003קטן מהכיל\"\u0004 (מלכים א ח, סד)? אין הכוונה למזבח שבנה שלמה בבית המקדש, כפי שמבין ר' יהודה, אלא למזבח הנחושת של משה, שנפסל לשימוש מאותו יום. ואף שקוטנו של מזבח זה לא היה הסיבה לקידוש העזרה, הכתוב משתמש בלשון נקיה, \u0003כאדם האומר לחבירו \"פלוני ננס הוא\", ו\u0004כוונתו לומר שהוא \u0003פסול לעבודה.\u0004","ושואלים: \u0003ור' יהודה,\u0004 מה הוא אומר? \u0003שפיר קאמר\u0004 \u0005[יפה אמר]\u0006 \u0003ר' יוסי!\u0004 ומשיבים: \u0003ר' יהודה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר:\u0004 \u0003מזבח שעשה משה גדול היה,\u0004 ולא קטן כמו שנראה מפשטות הכתובים. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 נאמר במזבח: \u0003\"חמש אמות ארך וחמש אמות רחב\"\u0004 (שמות כז, א), \u0003דברים\u0004 אלו \u0003ככתבן, דברי ר' יוסי.\u0004","\u0003ר' יהודה אומר: נאמר כאן \"רבוע\" ונאמר להלן\u0004 במזבח שמתאר הנביא יחזקאל \u0003\"רבוע\"\u0004 (יחזקאל מג, טז), \u0003מה להלן,\u0004 במזבח יחזקאל, אנו אומרים ש\"רבוע\" עניינו ש\u0003מאמצעיתו היה מודד\u0004 שתים עשרה אמה לכל צד, \u0003אף כאן מאמצעיתו היה מודד\u0004 חמש אמות לכל צד, ונמצא שלדעתו היה המזבח עשר על עשר אמות, ולא חמש על חמש. ולפי חשבון זה, לא היה די במזבח שעשה שלמה כדי להקריב את כל הקרבנות ביום חנוכת המקדש, ולכן קידש את העזרה להקרבה.","ושואלים: \u0003והתם מנלן\u0004 \u0005[ושם,\u0006 במזבח יחזקאל, \u0005מנין לנו]\u0006 שמאמצעיתו \u0005הוא מודד?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והאריאל שתים עשרה\u0004 אורך בשתים עשרה רוחב רבוע אל ארבעת רבעיו\" (יחזקאל מג, טז), והכוונה היא שתים עשרה \u0003אמה לכל רוח\u0004 כלומר, מנקודת האמצע, ובסך הכל עשרים וארבע אמות על עשרים וארבע אמות. \u0003או אינו אלא שתים עשרה על שתים עשרה\u0004 בסך הכל? \u0003כשהוא אומר: \"אל ארבעת רבעיו\", מלמד\u0004 הכתוב \u0003שמאמצע הוא מודד.\u0004","ושואלים: \u0003ור' יוסי,\u0004 מה הוא אומר על גזירה שווה זו? ומשיבים: \u0003כי גמר\u0004 \u0005[כאשר\u0006 הוא \u0005לומד]\u0006 \u0003גזירה שוה,\u0004 לגבי \u0003גובהה הוא דגמיר\u0004 \u0005[שלומד].\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר במזבח של משה: \u0003\"ושלש אמות קומתו\"\u0004 (שמות כז, א), \u0003דברים\u0004 אלו הריהם \u0003ככתבן,\u0004 אלו \u0003דברי ר' יהודה,\u0004 שזה היה גובה המזבח.","\u0003ר' יוסי אומר: נאמר כאן \"רבוע\", ונאמר להלן,\u0004 במזבח הקטורת, \u0003\"רבוע\"\u0004 (שמות ל, ב), \u0003מה להלן\u0004 במזבח הקטורת \u0003גובהו\u0004 (אמתיים) \u0003פי שנים כארכו\u0004 (אמה), \u0003אף כאן\u0004 מזבח העולה היה גובהו עשר אמות, \u0003פי שנים כארכו,\u0004 שהיה חמש אמות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהודה: והלא כבר נאמר \"ואת החצר מאה אמה וקומה חמש אמות\" וגו'\u0004 (ראה שמות כז, יח), הרי קלעי חצר המשכן היו בגובה של חמש אמות, ולשיטתך, \u0003אפשר כהן עומד על גבי המזבח ועבודה בידו, וכל העם רואין אותו מבחוץ?\u0004 והרי אין דרך כבוד בכך!","\u0003אמר לו ר' יוסי: והלא כבר נאמר \"ואת קלעי החצר ואת מסך\u0004 פתח \u0003שער החצר אשר על המשכן ועל המזבח\"\u0004 (במדבר ד, כו), ויש ללמוד מכאן שהוקשו זה לזה: \u0003מה משכן\u0004 היה גבוה \u0003עשר אמות\u0004 (שמות כו, טז), \u0003אף מזבח\u0004 היה \u0003עשר אמות. ואומר\u0004 מצד אחר ביחס לקלעי החצר: \u0003\"קלעים חמש עשרה\u0004"],["\u0003אמה אל הכתף\"\u0004 (ראה שמות לח, יד), \u0003ו\u0004לפי זה, \u0003מה תלמוד לומר\u0004 לגבי גובה הקלעים \"וקומה \u0003חמש אמות\"\u0004 (שמות כז, יח)? הכוונה היא ש\u0003משפת מזבח ולמעלה\u0004 היו חמש אמות.","\u0003ו\u0004כן לשיטתי, שגובהו של המזבח היה עשר אמות, \u0003מה תלמוד לומר:\u0004 \"ועשית את המזבח... \u0003ושלש אמות קומתו\"\u0004 (שמות כז, א)? הכוונה היא \u0003לשלש אמות משפת סובב ולמעלה.\u0004","ושואלים: \u0003ור' יהודה,\u0004 שסבור שגובה המזבח היה שלוש אמות, כפשט הכתוב, מה הוא עושה בגזירה שווה \"רבוע\" \"רבוע\" למזבח הקטורת, ממנה למד ר' יוסי שגובהו היה עשר אמות? ומשיבים: \u0003כי גמיר\u0004 \u0005[כאשר\u0006 הוא \u0005לומד]\u0006 \u0003גזירה שוה\u0004 של \"רבוע\" \"רבוע\" — \u0003ברחבה הוא דגמיר\u0004 \u0005[שלומד],\u0006 שיש למדוד את מידת רוחבו מן האמצע לכל רוח. ומן המזבח שביחזקאל הוא לומד, כפי שנאמר בעמוד הקודם, ולא ממזבח הקטורת.","ועוד שואלים: \u0003ולר' יהודה,\u0004 הסבור שגובה המזבח היה שלוש אמות בלבד, \u0003הא\u0004 \u0005[הרי]\u0006 גם לשיטתו \u0003קא מיתחזי\u0004 \u0005[נראה]\u0006 ה\u0003כהן\u0004 כשהוא עובד על המזבח, שהרי לדעתו גובה הקלעים אינו אלא חמש אמות! ומשיבים: \u0003נהי\u0004 \u0005[אמנם]\u0006 ה\u0003כהן מיתחזי\u0004 \u0005[נראה],\u0006 אבל \u0003עבודה\u0004 ש\u0003בידו לא מיתחזי\u0004 \u0005[נראית].\u0006 ושבים למחלוקת הראשונה בין ר' יהודה ור' יוסי, האם קידש שלמה את רצפת העזרה עצמה להקרבה.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה\u0004 שסבור כן, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"קידש\u0004 המלך את תוך החצר\" (מלכים א ח, סד), \u0003אלא לר' יוסי מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"קידש\"?\u0004 ומשיבים: הכוונה היא שקידש את החצר בקדושת העזרה, כחצר המשכן, \u0003להעמיד בה מזבח.\u0004","ומן הצד האחר שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לר' יוסי,\u0004 הסבור שמזבח הנחושת של משה היה בגודל חמש אמות על חמש אמות, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 שהיה מזבח הנחושת (שעשה משה) \u0003\"קטן\u0004 מהכיל\", \u0003אלא לר' יהודה\u0004 הסבור שהיתה מערכתו עשר אמות רבועות, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"קטן\"?\u0004 ומשיבים: לשיטתו אין מדובר בפסוק זה על מזבח שעשה משה, אלא על המזבח שבנה שלמה במקדש, והכתוב \"כי מזבח הנחושת קטון מהכיל\", \u0003הכי קאמר\u0004 \u0005[כך אומר]:\u0006 \u0003מזבח אבנים שעשה שלמה תחת מזבח הנחשת קטן הוה\u0004 \u0005[היה].\u0006","ושבים למחלוקת שביניהם, מהיכן למדים גזירה שווה \"רבוע\" \"רבוע\" למזבח העולה, האם ממזבח הקטורת או מן המזבח שביחזקאל, ושואלים: \u0003במאי פליגי\u0004 \u0005[במה\u0006 באיזה עקרון הם \u0005חלוקים]?\u0006 ומסבירים: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יהודה, \u0005סבור]:\u0006 \u0003דנין חוץ מחוץ\u0004 מזבח העולה ממזבח העולה שביחזקאל, \u0003ואין דנין\u0004 מזבח העולה שהוא ב\u0003חוץ מ\u0004מזבח הקטורת שהוא ב\u0003פנים.\u0004","\u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יוסי, \u0005סבור]:\u0006 \u0003דנין כלי מכלי\u0004 מזבח הנחושת ממזבח הקטורת, ששניהם היו ניידים, \u0003ואין דנין כלי מבנין,\u0004 והמזבח שביחזקאל עשוי היה אבנים.","\u0003אמר רבא:\u0004 אף שר' יהודה סבור שרצפת העזרה נתקדשה בקדושת המזבח, \u0003מודה ר' יהודה בדמים\u0004 שלא היה זה אלא להקטרת אימורים, ולא לזריקת הדם עליה. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: כוס אחד היה ממלא מדם התערובות\u0004 של כל הדמים שהיו על רצפת העזרה בערב פסח, \u0003ושופכו על גבי מזבח, שאם\u0004 יקרה ש\u0003ישפך דמו של אחת מהן\u0004 מן הפסחים, ולא נזרק על גבי המזבח, \u0003נמצא\u0004 דם \u0003זה\u0004 ששופך עכשיו \u0003מכשירו.\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 \u0003סבר\u0004 \u0003ר' יהודה\u0004 כי \u0003כולה\u0004 \u0005כל\u0006 ה\u0003עזרה מיקדשא\u0004 \u0005[מקודשת]\u0006 בקדושת מזבח, \u0003הא איתעבידא ליה מצוותיה\u0004 \u0005[הרי נעשתה לו\u0006 כבר \u0005המצוה]\u0006 כשהדמים נשפכו על רצפת העזרה.","ודוחים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 אין הוא מצריך לשפוך מדם התערובות, אלא \u0003משום דקסבר\u0004 \u0005[שסבור הוא]:\u0006 \u0003שפיכה\u0004 של דם הפסח \u0003מכח האדם בעינן\u0004 \u0005[צריכים אנו],\u0006 ולא משום שצריך לעשות זאת על המזבח! \u0003ואומרים:\u0004 \u0003אם כן, נשקליה ונשפיך ליה אדוכתיה\u0004 \u0005[יקח אותו,\u0006 את הדם שאסף \u0005וישפוך אותו במקומו]\u0006 על הרצפה, ולאו דווקא על המזבח!","ועוד דוחים את ראייתו של רבא: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 לא הצריך ר' יהודה לזרוק את הדם על המזבח \u0003אלא\u0004 \u0003משום דבעינן\u0004 \u0005[שצריכים אנו]\u0006 \u0003מצוה מן המובחר,\u0004 שהכל מודים שהמצוה לכתחילה היא לזרוק על המזבח עצמו. ובאמת, גם על הרצפה היה הדבר כשר.","\u0003אמר ר' אלעזר: מזבח שנפגם, אין אוכלים בגינו\u0004 (בגללו, בשבילו) \u0003שירי מנחה, שנאמר\u0004 לאהרן ובניו: \"קחו את המנחה... \u0003ואכלוה מצות אצל המזבח\u0004 כי קדש קדשים היא\" (ויקרא י, יב), \u0003וכי אצל המזבח\u0004 דווקא \u0003אכלוה? אלא\u0004 לומר, \u0003בזמן ש\u0004המזבח \u0003הוא שלם ולא בזמן שהוא חסר.\u0004","\u0003אשכחן\u0004 \u0005[מצאנו]\u0006 ש\u0003שירי מנחה\u0004 נאכלים דווקא כשהמזבח שלם, \u0003קדשי קדשים מנלן\u0004 \u0005[מנין לנו]\u0006 שאין לאוכלם כשהמזבח פגום? \u0003תלמוד לומר: \"קדש\u0004 \u0003קדשים\u0004 היא\", ללמד בגזירה שווה שכל שנאמר בו קדש הקדשים דינו כן.","\u0003קדשים קלים מנין\u0004 שכך דינם? \u0003אמר אביי: אתיא מדרשא\u0004 \u0005[בא,\u0006 נלמד הדבר \u0005מהדרשה]\u0006 של \u0003ר' יוסי. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יוסי אומר שלשה דברים משום\u0004 (בשם)"],["\u0003שלשה זקנים,\u0004 בשם כל אחד מסר הלכה אחרת, \u0003וזה אחד מהן, ר' ישמעאל אומר: יכול יעלה אדם מעשר שני\u0004 שהפריש מתבואתו \u0003לירושלים ויאכלנו\u0004 גם \u0003בזמן הזה\u0004 שבית המקדש אינו קיים? \u0003ו\u0004לכאורה \u0003דין הוא: בכור טעון הבאת מקום\u0004 (לירושלים) כדי להקריבו ולאוכלו, \u0003ומעשר טעון הבאת מקום, מה בכור אינו\u0004 מובא ונאכל בירושלים \u0003אלא בפני הבית, אף מעשר אינו אלא בפני הבית.\u0004","ויש לדחות את ההשוואה: \u0003מה לבכור שכן טעון מתן דמים ו\u0004הקרבת \u0003אימורים לגבי מזבח,\u0004 ושמא בגלל זה אינו מובא שלא בפני הבית!","ואומרים: \u0003ביכורים יוכיחו,\u0004 שאין בהם מתן דמים למזבח, ובכל זאת אין מביאים בזמן הזה! ודוחים: \u0003מה לביכורים שכן טעונין הנחה\u0004 לפני המזבח, שנאמר \"ולקח הכהן הטנא מידך והניחו לפני מזבח ה' אלקיך\" (דברים כו, ד), ולכן אינם נוהגים אלא בזמן שהמקדש קיים. אבל מעשר שני — הרי אין מביאים אותו אלא לירושלים!","\u0003תלמוד לומר: \"והבאתם שמה עלתיכם\u0004 וזבחיכם ואת מעשרותיכם... ובכורות בקרכם וצאנכם\" (דברים יב, ו), \u0003מקיש מעשר לבכור, מה בכור אינו אלא בפני הבית, אף מעשר אינו אלא בפני הבית.\u0004 תחילה שואלים על דרך ההוכחה: ומדוע הוצרך להיקש של בכור למעשר?","\u0003וניהדר דינא וניתי\u0004 \u0005[ושיחזור הדין ויבוא,\u0006 ויילמד הדבר\u0005]\u0006 מבכור וביכורים \u0003ב\"מה הצד\",\u0004 כדרך בנין אב, שאף שיש בכל אחד מהם דין מיוחד, יש בהם צד משותף שטעונים הבאת מקום, ואין מביאים אותם אלא בפני הבית, וממנו נלמד למעשר!","ומשיבים: \u0003משום דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך]:\u0006 \u0003מה להצד השוה שבהן שכן יש בהן\u0004 בשניהם \u0003צד מזבח\u0004 כל אחד בעניינו, מה שאין כן במעשר.","ומעתה יש לשאול: \u0003מאי קסבר\u0004 \u0005[מה סבור]\u0006 ר' ישמעאל שהוא מוכיח מבכור למעשר? \u0003אי קסבר\u0004 \u0005[אם סבור הוא]:\u0006 \u0003קדושה ראשונה\u0004 שנתקדש מקום המקדש, \u0003קידשה לשעתה וקידשה לעתיד לבא\u0004 גם לאחר החורבן, הרי יש אפשרות לבנות מזבח ולהקריב עליו גם אם בית המקדש אינו בנוי, ואם כן \u0003אפילו בכור נמי\u0004 \u0005[גם כן]\u0006 יביא! \u0003ואי קסבר\u0004 \u0005[ואם סבור הוא]:\u0006 קדושה ראשונה \u0003לא קידשה לעתיד לבא,\u0004 \u0003אפילו\u0004 לגבי \u0003בכור נמי תיבעי\u0004 \u0005[גם כן תישאל]\u0006 השאלה!","\u0003אמר רבינא: לעולם קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003לא קידשה\u0004 לעתיד לבוא, \u0003ו\u0004אף שלדרך זו לא ניתן להקריב בכור, וממילא גם לא לאוכלו, \u0003הכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]?\u0006 במקרה מיוחד, \u0003בבכור שנזרק דמו קודם חורבן הבית, וחרב הבית ועדיין בשרו\u0004 של הבכור \u0003קיים. ו\u0004נאסר לאכול את בשרו משום ש","\u0003איתקש\u0004 \u0005[הוקש]\u0006 בכתוב \u0003בשרו לדמו,\u0004 שנאמר \"את דמם תזרוק ואת חלבם תקטיר ובשרם יהיה לך\" (במדבר יח, יז—יח) — \u0003מה דמו במזבח, אף בשרו\u0004 נאכל רק כשיש \u0003מזבח. ו\u0004כפי שנאמר לעיל, \u0003אתי\u0004 \u0005[בא]\u0006 \u0003מעשר ויליף\u0004 \u0005[ולמד]\u0006 בהיקש \u0003מבכור.\u0004","ושואלים: \u0003וכי דבר הלמד בהיקש חוזר ומלמד בהיקש\u0004 בקדשים? ומשיבים: \u0003מעשר דגן חולין הוא,\u0004 ולא חל על כך הכלל שאין הלמד בהיקש חוזר ומלמד.","ואומרים: \u0003הניחא למאן דאמר בתר למד אזלינן\u0004 \u0005[זה\u0006 \u0005נוח ל\u0006דעת \u0005מי שאומר,\u0006 לגבי כלל זה, ש\u0005אחר למד הולכים אנו],\u0006 והלמד איננו בקדשים, \u0003אלא למאן דאמר בתר מלמד אזלינן\u0004 \u0005[ל\u0006דעת \u0005מי שאומר\u0006 ש\u0005אחר מלמד הולכים אנו],\u0006 והמלמד כאן הרי הוא בקדשים, אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומשיבים: \u0003דם ובשר\u0004 לא הוקשו בכתוב זה לזה, אלא \u0003חדא מילתא היא\u0004 \u0005[דבר אחד הוא],\u0006 שמובן מעצמו שיש להם אותו דין, וממילא אין כאן אלא היקש אחד מבכור למעשר. ועל כל פנים, מן הבכור למדנו שבזמן שאין מזבח, וכיוצא בזה בזמן שהוא פגום — אין קדשים קלים נאכלים.","מסופר, \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003רבין\u0004 לארץ ישראל \u0003אמרה לשמעתא קמיה\u0004 \u0005[לשמועה זו לפני]\u0006 \u0003ר' ירמיה\u0004 שאף קדשים קלים נפסלים בפגימת המזבח. \u0003אמר: בבלאי טפשאי\u0004 \u0005[הבבלים הטפשים],\u0006 \u0003אמטול דיתבי בארעא חשוכא אמרי שמעתא דמחשכא\u0004 \u0005[משום ש\u0006הם \u0005יושבים בארץ חשוכא אומרים הלכות חשוכות]!\u0006 האם \u0003לא שמיע להו הא דתניא\u0004 \u0005[שמעו את זה ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003בשעת סילוק מסעות\u0004 במדבר, כאשר המחנה הלך במסעותיו, \u0003קדשים נפסלין\u0004 ואינם נאכלים, שהרי המזבח אינו במקומו, \u0003ו\u0004אולם \u0003זבים ומצורעים משתלחים חוץ למחיצה\u0004 (זב חוץ למחנה לויה ומצורע חוץ למחנה ישראל).","\u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003בשני מקומות קדשים נאכלים,\u0004 גם בזמן החנייה וגם בשעת סילוק מסעות. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 מדובר \u0003בקדשי קדשים,\u0004 שנפסלים ואינם נאכלים כשהמזבח אינו במקומו, \u0003הא\u0004 \u0005[זה]\u0006 \u0003בקדשים קלים,\u0004 שנאכלים גם כשאין מזבח, ושלא כדברי אביי?","\u0003אמר רבינא:\u0004 לא, אין זה הפתרון היחיד. אפשר להסביר כי \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 עוסקים \u0003בקדשים קלים, ולא קשיא\u0004 \u0005[ואינו קשה]:\u0006"],["\u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003ר' ישמעאל,\u0004 שהוא לומד בשר מדם שאם אין מזבח — נפסל הבשר באכילה, \u0003הא רבנן\u0004 \u0005[זו\u0006 שיטת \u0005חכמים]\u0006 החולקים עליו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא והא\u0004 \u0005[זה וזה]\u0006 מדובר \u0003בקדשי קדשים, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 שניתן לאכול את הבשר \u0003\"בשני מקומות\"?\u0004 בשני המקרים מדובר כאשר המזבח מונח במקומו, ולא בזמן מסע, אלא שבמקרה אחד מדובר \u0003קודם שיעמידו לוים את המשכן,\u0004"],["\u0003ו\u0004המקום האחר — \u0003לאחר שיפרקו הלוים את המשכן,\u0004 הואיל ועדיין מזבח במקומו — מותר לאכול שם קדשי קדשים.","\u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 הואיל והמשכן מפורק \u0003איפסיל להו\u0004 \u0005[נפסלו להם\u0006 הקדשים\u0005]\u0006 \u0003ב\u0004דין \u0003יוצא,\u0004 שהרי שוב אין שם מחיצות לאכילת קדשים, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שניתן לאכול כך קדשים.","ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור\u0006 ש\u0005כך הוא גם כן]\u0006 שייפסל ביוצא! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ונסע אהל מועד\"\u0004 (במדבר ב, יז), לומר \u0003אף על פי שנסע\u0004 — \u0003אהל מועד הוא,\u0004 ולא בטלה קדושתו.","ועוד בענין המזבח, \u0003אמר רב הונא אמר רב: מזבח של\u0004 המשכן שהיה ב\u0003שילה של אבנים היה,\u0004 ולא מזבח מיטלטל כשל משה. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' אליעזר בן יעקב אומר, מה תלמוד לומר\u0004 \"מזבח \u0003אבנים\"\u0004 (שמות כ, כב), \u0003\"אבנים\"\u0004 (דברים כז, ה), \u0003\"אבנים\"\u0004 (דברים כז, ו), \u0003שלש פעמים?\u0004 לרמז שהיו שלושה מזבחות אבנים, \u0003אחד של שילה, ואחד של נוב וגבעון, ו\u0004מזבח של \u0003בית עולמים,\u0004 של המקדש.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב אחא בר אמי\u0004 ממה ששנינו: \u0003אש שירדה מן השמים בימי משה\u0004 בחנוכת המשכן (ראה ויקרא ט, כד) \u0003לא נסתלקה מעל מזבח הנחושת אלא בימי שלמה\u0004 כשבנה מזבח אבנים במקומו, \u0003ואש שירדה בימי שלמה\u0004 על מזבח האבנים שבנה, \u0003לא נסתלקה עד שבא מנשה וסילקה,\u0004 שהרס את המזבח. \u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לדברי רב הונא, שמזבח של שילה של אבנים היה — \u0003מעיקרא הוא דאיסתלק ליה\u0004 \u0005[מתחילה הוא שהסתלקה לה]\u0006 כבר, כאשר נבנה המזבח בשילה במקום מזבח הנחושת, ולא בימי שלמה!","ומשיבים: \u0003הוא,\u0004 רב הונא, ש\u0003אומר\u0004 כדברי \u0003ר' נתן. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' נתן אומר: מזבח של שילה של נחושת היה, חלול ומלא אבנים.\u0004","\u0003רב נחמן בר יצחק אמר:\u0004 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא נסתלקה\"?\u0004 כוונתו \u0003לא נסתלקה לבטלה,\u0004 שאף שנבנה מזבח של אבנים בשילה, נשאר שם המזבח של משה, ולא בטלה ממנו האש לחלוטין, גם כשהיה מזבח אחר. ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 שלא נסתלקה לגמרי? \u0003רבנן אמרי\u0004 \u0005[חכמים אומרים]:\u0006 \u0003שביבא הוה משדרא\u0004 \u0005[ניצוץ היתה שולחת]\u0006 האש ממזבח משה אל המזבח הגדול. \u0003רב פפא אמר: אושפיזא הוה נקט\u0004 \u0005[\u0006כ\u0005אורח היה נעשה]\u0006 \u0003וזימנין הכא וזימנין הכא\u0004 \u0005[ופעמים כאן,\u0006 במזבח הנחושת, היתה האש, \u0005ופעמים כאן,\u0006 במזבח האבנים\u0005].\u0006","ועוד בענין המזבח, \u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 במסכת מדות: מתחילה היה המזבח בגודל עשרים ושמונה על עשרים ושמונה אמה. \u0003וכשעלו בני הגולה\u0004 מגלות בבל, \u0003הוסיפו עליו\u0004 על מידות המזבח שהיה בבית ראשון, עוד \u0003ארבע אמות מן הדרום\u0004 (לכל אורכו) \u0003וארבע אמות מן המערב כמין\u0004 צורת \u0003גמא\u0004 יוונית, זוית ישרה. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר רב יוסף: משום\u0004 ש\u0003לא ספק\u0004 \u0005[הספיק\u0006 המזבח\u0005],\u0006 והיה צריך לעשות לו מקום מערכה גדול יותר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי, השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003מקדש ראשון דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"יהודה וישראל רבים כחול אשר על (שפת) הים\"\u0004 (מלכים א ד, כ) — \u0003ספק\u0004 \u0005[הספיק]\u0006 המזבח, \u0003מקדש שני דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"כל הקהל כאחד ארבע רבוא\u0004 אלפים שלש מאות ששים\" (עזרא ב, סד), \u0003לא ספק\u0004 \u0005[הספיק]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אין זו קושיה, \u0003התם\u0004 \u0005[שם]\u0006 בבית ראשון \u0003אש של שמים מסייעתן,\u0004 לכן היה הכל נשרף אף במערכה קטנה יותר\u0003,\u0004 \u0003הכא\u0004 \u0005[כאן]\u0006 בבית שני \u0003אין אש של שמים מסייעתן.\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין אמר ר' שמעון בן פזי משום\u0004 (בשם) \u0003בר קפרא\u0004 בטעם הדבר, מדוע הגדילו את שטח המזבח: את מקום ה\u0003שיתין,\u0004 הבורות, לשם היו הנסכים יורדים מאותה קרן, \u0003הוסיפו\u0004 על המזבח בבית שני, וכשבנו את התוספת עשו שם נקבים בראש המזבח, משם הגיעו עד לאותו בור. ומדוע? \u0003מעיקרא סבור\u0004 \u0005[מתחילה סברו]:\u0006 מה שנאמר \u0003\"מזבח אדמה\u0004 תעשה לי\" (שמות כ, כא) כוונתו — \u0003שהוא אטום באדמה,\u0004 שאין בו נקבים וחללים בכלל.","\u0003ולבסוף סבור\u0004 \u0005[סברו]:\u0006 \u0003שתיה\u0004 של מזבח, הנסכים הנשפכים עליו, צריכה להיות \u0003כאכילה\u0004 שגם הנסכים צריכים להינתן במזבח עצמו, ולא לנזול לצידו. \u0003ו\u0004לפי זה \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מזבח אדמה?\u0004 לומר \u0003שהוא מחובר באדמה, שלא יבננו לא על גבי כיפים\u0004 (קשתות),"]]};
